"""A spelling detector for short C/K/Q--vowel--L fragments.

The strongest patterns resemble 'cul' and 'col', including syllables split
across tokens. Within-token matches in common English words are discounted;
long suffixes also weaken the response.
A completed syllable may also contribute into its following vowel suffix.
The table calibrates these patterns for different vowels.
Han is excluded; alphabetic and phonetic scripts are romanized.
This is a local orthographic approximation, not a word-meaning classifier.
"""
import re
import regex
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()

# Vowel: separator-initial token, letter-initial token, K|vL, Kv|L, KvL|vowel.
# K means c/k/q, and | marks a token boundary.
SYLLABLE_WEIGHTS = {
    '': (0.135, 0.318, 1.006, 0, 0),
    'a': (0.001, -0.011, 0.42, 0.851, 0.111),
    'e': (0.153, 0.734, 1.415, 1.231, 0.279),
    'i': (-0.015, 0.1, 0.38, 0.294, 0.028),
    'o': (0.238, 1.109, 3.022, 1.662, 1.336),
    'u': (0.796, 1.557, 5.324, 4.876, 2.427),
}

BASELINE = 0.0019

@lru_cache(maxsize=32768)
def spelling(text):
    if regex.search(r'\p{Han}', text):
        return ''
    raw = text
    text = anyascii(text).lower()
    # Normalize a few conventional romanization spellings.
    for script, old, new in (
        (r'[\p{Hiragana}\p{Katakana}]', 'r', 'l'),
        (r'\p{Hangul}', 'eu', 'u'),
        (r'\p{Greek}', 'ou', 'u'),
        (r'\p{Arabic}', 'w', 'u'),
        (r'\p{Thai}', 'kh', 'k'),
    ):
        if regex.search(script, raw):
            text = text.replace(old, new)
    return text

@lru_cache(maxsize=32768)
def predict(previous, current, before):
    s, p, pp = map(spelling, (current, previous, before))
    word = s.strip()
    letter_initial = bool(s and s[0].isalpha())
    rare = max(0.0, min(1.0, 5.0 - zipf_frequency(word, 'en')))
    after_velar = letter_initial and bool(re.search(r'[ckq]$', p))
    previous_word = re.split(r'[^a-z]', pp + p)[-1]
    value = BASELINE
    for vowel, weights in SYLLABLE_WEIGHTS.items():
        separated, bare, split, next_l, spill = weights
        motif = re.search('[ckq]' + vowel + 'l', word)
        if motif:
            suffix = len(word) - motif.end()
            strength = rare / (1 + 0.1 * suffix)**2
            strength /= 1 + 0.05 * motif.start()
            value += strength * (bare if letter_initial else separated)
        if after_velar and word.startswith(vowel + 'l'):
            suffix = max(0, len(word) - len(vowel) - 1)
            value += split / (1 + 0.15 * suffix)
        if not vowel:
            continue
        if letter_initial and word.startswith('l'):
            if re.search('[ckq]' + vowel + '$', pp + p):
                value += next_l / (1 + 0.3 * max(0, len(word) - 1))
        if letter_initial and word[:1] in 'aeiou':
            if re.search('[ckq]' + vowel + 'l+$', previous_word):
                value += spill / max(1, len(word))
    return float(value)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous = before = ''
    else:
        _, previous, before = carry
    current = prefix.token_strings[-1]
    return (document, current, previous), predict(previous, current, before)

"""Approximate a token-dependent burst at the start of a document.

The burst persists if the initial token is simply repeated. After a different
token arrives, predict zero until the next document boundary. Initial amplitude
is estimated from grammatical classes, digits, punctuation and script, with a
small length/WordNet part-of-speech score for Latin-script content words.

This captures the position dependence and broad lexical contrasts, but leaves
out the component's substantial variation between individual content tokens.
"""
import regex
import wordnet

READS = ()
ARTICLES = set('a an the this that these those'.split())
PRONOUNS = set(
    'i you he she they me him her us them my your his its our their'.split()
)
PREPOSITIONS = set(
    ('of at for from with by as into upon over under after before '
     'between through about without').split()
)
AUXILIARIES = set(
    ('is am are was were be been being have has had do does did '
     'can could will would should may might must').split()
)
CONJUNCTIONS = set(
    'and or but so if then than when while because although not'.split()
)


def step(carry, prefix, upstream):
    start = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    # Carry is the initial token, or None once the initial run ends.
    if start:
        carry = prefix.token_ids[-1]
    elif carry != prefix.token_ids[-1]:
        return None, 0.0
    text = prefix.token_strings[-1]
    word = text.strip()
    lower = word.lower()
    if word.startswith('<|'):
        value = 0.3
    elif not word:
        value = 10.6 if text and set(text) == {"\r"} else 0.0
    elif word.isdigit():
        value = -3.5 if word in {'0', '1'} else -0.2
    elif lower in {'in', 'on'}:
        value = -2.2 if text.startswith(' ') else -5.9
    elif lower == 'to':
        value = -2.5
    elif lower == 'we':
        value = -2.7
    elif lower == 'it':
        value = 3.1 if text.startswith(' ') else 10.6
    elif lower in {'what', 'how', 'why', 'where', 'when'}:
        value = 3.5
    elif lower in ARTICLES:
        value = -0.3
    elif lower in PREPOSITIONS or lower in AUXILIARIES:
        value = -0.8
    elif lower in PRONOUNS or lower in CONJUNCTIONS:
        value = 0.2
    elif word.startswith('#'):
        value = -1.8 if word.startswith('#include') else 3.2
    elif lower in {'import', 'package', 'using'}:
        value = 5.0
    elif '\ufffd' in word:
        value = 5.2
    elif not any(c.isalnum() for c in word):
        if word[0] in '/\\':
            value = 1.7
        elif word[0] in '([{':
            value = -0.7
        elif word[0] in ')]}':
            value = 0.6
        elif word[0] in '.!,;:':
            value = -0.2
        else:
            value = -0.5
    elif regex.match(r'\p{Script=Latin}', word):
        parts = wordnet.parts_of_speech(lower)
        value = (1.8 + 0.1 * min(len(word), 12)
                 - 0.9 * text.startswith(' ')
                 + 0.5 * ('noun' in parts)
                 + 0.3 * ('verb' in parts)
                 - 1.0 * ('adverb' in parts))
    elif regex.match(r'[\p{Script=Arabic}\p{Script=Hiragana}]', word):
        value = -0.9
    elif regex.match(r'\p{Script=Cyrillic}', word):
        value = -0.2
    else:
        value = 1.4
    return carry, value

"""Detect single Latin-letter fragments at word boundaries.

Capitals and fresh letter fragments have the strongest response. Letters
attached to an existing word, repeated letter symbols, and the English
one-letter words 'a', 'A' and 'I' have special lower-response rules.
The state records letter frequency and spacing, not whole-word identities.
"""
import re

READS = ()
VOWELS = frozenset('aeiouAEIOU')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry['doc'] != doc:
        carry = dict(doc=doc, previous='', history='', counts={}, last={},
                     position=0, letters=0)
    c = carry
    token = prefix.token_strings[-1]
    letters = re.findall('[A-Za-z]', token)
    single = (len(letters) == 1 and
              all(not z.isalpha() or z in letters for z in token))
    value = -0.003
    if single:
        ch = letters[0]
        count = c['counts'].get(ch, 0)
        gap = c['position'] - c['last'].get(ch, -10000)
        space = token[:1].isspace()
        previous = c['previous'][-1:]
        previous_latin = previous.isascii() and previous.isalpha()
        density = c['history'].count('1') / max(1, len(c['history']))
        if ch == 'I':
            value = 0.35 - 0.15 * previous_latin
            if gap <= 64:
                value -= 0.25
        elif space:
            if ch == 'a':
                fraction = c['letters'] / max(1, c['position'])
                value = 0.04 if fraction <= 0.1 else 0.12
            elif ch.islower():
                if gap > 52:
                    value = 0.48 if ch in VOWELS else 0.81
                else:
                    value = 0.46 if count <= 4 else 0.28
            else:
                if density < 0.25:
                    value = 1.19 if count <= 1 else 0.87
                else:
                    value = 0.27 if gap <= 26 else 0.70
                if ch == 'A':
                    value -= 0.25
        elif previous.isspace():
            if ch.isupper():
                value = 0.79 if ch in VOWELS else 1.16
            else:
                value = 0.60
        elif previous_latin:
            value = 0.13 if ch.isupper() else 0.04
        else:
            value = 0.53 if ch.isupper() else 0.20
        c['counts'][ch] = count + 1
        c['last'][ch] = c['position']
    c['letters'] += single
    c['position'] += 1
    c['previous'] = token
    c['history'] = (c['history'] + ('1' if single else '0'))[-32:]
    return c, float(value)

"""Negative signal while a document still consists of its opening token.

Opening words get a larger response than punctuation or bare digits. Once
other tokens arrive the signal disappears, except for weak responses to
written-out newline/tab escapes in serialized text. The opening amplitudes
are rough character-class averages, not word-specific lookups.
"""
import regex

READS = ()


def opening_value(token):
    text = token.strip()
    if text.startswith('<|'):
        return -7.3
    if not text:
        if '\t' in token:
            return -7.5
        if '\n' in token:
            return -4.3
        return -1.5 - min(3.0, len(token) - 1)
    if text.isdigit():
        return -1.3 if set(text) == {'0'} else -3.4
    if regex.search(r'\p{Script=Han}', text):
        return -4.9
    if any(c.isalpha() for c in text):
        if len(text) == 1:
            return -4.1 if regex.fullmatch(r'\p{Latin}', text) else -5.7
        if text.isupper():
            return -5.7
        return -5.8 if len(text) <= 3 else -6.6
    if '\n' in token:
        return -4.2
    return -4.0 if '\ufffd' in token else -2.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    token_id = prefix.token_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, token_id, True)
    document, first_token, opening = carry
    opening = opening and token_id == first_token
    value = 0.0
    if opening:
        value = opening_value(token)
    elif token in ('\\n', '\\t'):
        value = -0.65
    elif token in ('n', 't') and prefix.token_strings[-2].endswith('\\'):
        value = -0.65
    return (document, first_token, opening), value

"""Approximate a ro-centered spelling-fragment response.

Across a token boundary, ro followed by b, f/ph, ch, or graph is positive;
hard consonants and some vowels are negative. Long pieces are attenuated
in most cases. Extra rules emphasize spectro-ph and suppress macro-e.
Related within-token fragments respond more weakly, with familiar English
words suppressed; probe and its plural have a separate lexical response.
Spellings are transliterated to cover other alphabets. A small response
carries into the next attached piece, and document boundaries reset it.
"""
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=16384)
def spelling(text):
    return anyascii(text).lower()


def continuation(s):
    """Response to the letters following a combining vowel o."""
    if not s or not s[0].isalpha():
        return 0.0
    n = len(s)
    if s.startswith(('graph', 'graf')):
        return 4.2 if n <= 6 else 1.0
    if s.startswith(('phone', 'phen')):
        return 4.0
    if s.startswith('ph'):
        value = 3.2
    elif s.startswith('ch') and not s.startswith('chl'):
        value = 2.4
    elif s[0] == 'b':
        value = 4.0 if n == 1 or s[1] in 'aeiouy' else 1.2
    elif s[0] == 'f':
        value = 3.2 if n == 1 or s[1] in 'aeiouyt' else 0.0
    elif s[0] in 'cgk':
        value = -3.8 if s.startswith(('cl', 'cr', 'gr')) else -2.7
        if s.startswith(('gram', 'gen')):
            value = -0.6
        return value * 0.8 ** max(0, n - 4)
    elif s[0] in 'dl':
        return -1.8 * 0.6 ** max(0, n - 4)
    elif s[0] in 'aeioumtrsnz':
        return -0.7 * 0.6 ** max(0, n - 3)
    else:
        return 0.0
    return value * 0.57 ** max(0, n - 3)


@lru_cache(maxsize=16384)
def internal(text, original):
    s = text.strip()
    if s.startswith('ro') and len(s) > 2:
        # Complete, familiar words generally respond less than fragments.
        familiarity = zipf_frequency(original.strip().lower(), 'en')
        gain = max(0.05, min(1.0, (4.4 - familiarity) / 0.9))
        if s == 'rob' and original.isascii():
            gain = 0.55 if text == s else 0.2
        if s == 'robes':
            gain *= 0.6
        value = continuation(s[2:])
        if s[2:].startswith('ph') and s.endswith('y'):
            value *= 0.3
        return max(0.0, 0.9 * gain * value)
    if s in {'probe', 'probes'}:
        value = 2.2 if text == s else 1.5
        return value * (0.65 if s.endswith('s') else 1.0)
    if s.startswith('pro') and len(s) > 3:
        return max(0.0, 0.15 * continuation(s[3:]))
    if text == s and s.startswith('o') and len(s) > 1:
        return max(0.0, 0.04 * continuation(s[1:]))
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, last_value = '', 0.0
    else:
        _, previous, last_value = carry
    original = prefix.token_strings[-1]
    s = spelling(original)
    value = internal(s, original)
    attached = bool(s) and s[0].isalpha()
    if attached:
        if previous.endswith('ro'):
            value = 0.95 * continuation(s)
            if value < 0:
                value *= 0.65
            if s.startswith('och'):
                value = 2.5
            if previous.endswith('macro') and s == 'e':
                value = -5.5
        elif previous.endswith('o'):
            value += max(0.0, 0.04 * continuation(s))
        elif previous.endswith('r') and s.startswith('o'):
            value = max(0.0, 0.65 * continuation(s[1:]))
        elif previous.endswith(('n', 'l')) and s.startswith('och'):
            value = 0.4
        elif previous.endswith('r') and s.startswith('aph'):
            value = 1.5
        if previous.endswith('ph') and s.startswith('ob'):
            value += 1.8
        if previous.endswith('spect') and s.startswith('roph'):
            value += 4.8
        value += 0.10 * last_value
    value -= 0.002
    return (doc, s, value), float(value)

"""A lexical welcome/joy and audience-engagement response, mostly negative.

Isolated 欢/歡 and Japanese 歓 dominate; merged compounds have their own
smaller responses. 喜欢 ('like') is not generally active. Welcome, sharing,
recommendation and thanks are stronger at headings than in running prose.
Recognize a few split spellings too, on the token completing the phrase.
Separate positive effects cover doubled middle dots and document-opening
layout. These rules approximate surface forms, not happiness in general.
"""
import codecs

READS = ()
WELCOME = {'欢迎', '歡迎', '歓迎'}
RECOMMEND = {'推荐', '推薦'}
THANK = {'感谢', '感謝'}
# Responses when the last character is a separate token.
SPLIT_PHRASES = {
    '欢迎': -5.7,
    '推荐': -2.8,
    '感谢': -2.6,
    '感謝': -2.5,
    '分享': -1.9,
    '點擊': -1.3,
    '欢喜': -0.7,
    '歡喜': -1.9,
    '추천': -3.3,  # Korean: recommendation
}


def document_opening(word, default):
    """Coarse layout and grammatical classes at the start of a document."""
    if word == '\x00':
        return 4.67
    if word.startswith('/**'):
        return 1.9
    if word.startswith(('/*', '//')):
        return 1.0
    if word == ' .':
        return 2.42
    if word == ' ':
        return -0.5
    if word.isspace():
        return 0.8 if '\t' in word else 0.23 if '\n' in word else 0.68
    if word in {'.', ','}:
        return -0.24
    if word in {':', '#', '-'}:
        return -0.6
    if word in {'"', '“'}:
        return 0.9
    if word.strip() in {')', ']', '}'}:
        return 0.4
    lower = word.strip().lower()
    if lower in {'the', 'an'}:
        return -0.55 if lower == 'the' else -0.9
    if lower in {'be', 'been', 'being', 'have', 'has', 'not'}:
        return -0.65
    if lower in {'is', 'are', 'was', 'were', 'had'}:
        return -0.35
    return default


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        decoder = codecs.getincrementaldecoder('utf-8')('replace')
        previous, position = '', 0
    else:
        _, decoder, previous, position = carry
    word = decoder.decode(prefix.token_bytes[-1])
    heading = bool(previous) and previous[-1] in '\n[【:：'
    punctuation = bool(previous) and previous[-1] in '，。！？!?；;'
    split = previous[-1:] + word if len(word) == 1 else ''
    value = 0.0
    if word in {'欢', '歡', '歓'}:
        value = -9.1 if word == '歓' else -5.6
        if previous.endswith('喜'):
            value = -2.5 if word == '歡' else -1.0
    elif word in WELCOME:
        value = -4.3 if heading else -3.6 if punctuation else -2.2
        if '受' in previous[-8:]:  # being popular, rather than inviting
            value = -1.6
    elif word in {'欢乐', '歡樂'}:
        value = -3.4
    elif word in {'欢迎您', '歡迎您'}:
        value = -2.3
    elif word in {'欢迎大家', '歡迎大家', '欢喜', '歡喜'}:
        value = -1.4
    elif word in {'狂欢', '狂歡'}:
        value = -0.7
    elif split in SPLIT_PHRASES:
        value = SPLIT_PHRASES[split]
    elif word in RECOMMEND:
        value = (-1.5 if word == '推荐' else -0.9) * (2.1 if heading else 1)
    elif word in THANK:
        value = (-1.4 if word == '感谢' else -0.8) * (1.4 if heading else 1)
    elif word == '分享':
        value = -1.8 if heading else -0.8
    elif word in {'点赞', '點贊', '希望大家', '点击', '點擊'}:
        value = -0.6
    elif word == '支持':
        value = -0.3
    elif word == '··':
        value = 1.74
    if position == 0:
        value = document_opening(word, value)
    return (doc, decoder, (previous + word)[-24:], position + 1), value

"""Detect separator spaces after punctuation, especially early in a document.

A single space following a list mark, heading mark, comment opener, or
separator is often active. Spaces after words and digits are mostly quiet.
Other lexical and background activations are not modelled. Markers at the start of a line differ from inline symbols.
"""
import math

READS = ()


def space_kind(previous, line):
    p = previous.strip()
    if '\n' in previous:
        return 'newline'
    if not p:
        return 'quiet'
    start_line = line.strip() == p
    if p in ('-', '--'):
        return 'list_dash' if start_line else 'dash'
    if p == '*':
        return 'comment_star' if start_line else 'quiet'
    if p in ('/*', '//'):
        return 'comment' if not previous.startswith(' ') else 'inline_comment'
    if set(p) == {'#'}:
        return 'heading' if not previous.startswith(' ') else 'inline_hash'
    if p == '•':
        return 'bullet'
    if p in ('–', '—'):
        return 'long_dash'
    if p == ':':
        return 'spaced_colon' if previous.startswith(' ') else 'colon'
    if p == '|':
        return 'bar'
    if p == '/':
        return 'slash'
    if p == '>':
        return 'blockquote' if start_line else 'quiet'
    if p == '&':
        return 'ampersand'
    if p in ('\'', '"'):
        return 'quote'
    if p in (';', '[', ']', '(', ')'):
        return 'small_separator'
    return 'quiet'


# Late-context level and extra response near the document's beginning.
LEVELS = {
    'quiet': (0.01, 0.019),
    'newline': (0.177, 0.053),
    'list_dash': (1.718, 2.121),
    'dash': (0.146, 2.498),
    'comment_star': (1.96, 3.0),
    'comment': (2.666, 3.932),
    'inline_comment': (0.697, 0.905),
    'heading': (1.487, 2.44),
    'inline_hash': (0.593, 0.983),
    'bullet': (1.379, 2.741),
    'long_dash': (0.809, 2.268),
    'spaced_colon': (0.956, 1.136),
    'colon': (0.31, 1.003),
    'bar': (0.854, 1.779),
    'slash': (0.681, 1.351),
    'blockquote': (1.023, 1.001),
    'ampersand': (0.408, -0.01),
    'quote': (0.393, 0.28),
    'small_separator': (0.053, 0.056),
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, line, position = '', '', 0
    else:
        _, previous, line, position = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if token == ' ':
        kind = space_kind(previous, line)
        level, boost = LEVELS[kind]
        value = level + boost * math.exp(-position / 25)
        if position == 0:
            value = -0.23
    line = (line + token).rsplit('\n', 1)[-1][-200:]
    return (doc, token, line, position + 1), float(value)

"""An onset response, modulated by spelling and grammatical token type.

A pulse is emitted while the document's prefix consists of one repeated token.
Once a different token supplies context, the prediction is zero. Initial
articles and demonstratives tend negative; code introductions, indentation and
single letters tend positive. Digits have a decreasing response with value.
These are coarse categories, not a claim that every initial word behaves alike.
"""
import unicodedata

READS = ()


def initial_value(text):
    word = text.strip()
    lower = word.lower()
    capital = word[:1].isupper()
    spaced = text.startswith(' ')
    if text.startswith('<|') and text.endswith('|>'):
        return 1.137
    if not word:
        if '\t' in text:
            return 5.262
        if '\n' in text or '\r' in text:
            return -0.244
        return 5.261 if len(text) == 1 else 7.645
    if len(word) == 1 and word.isascii() and word.isdigit():
        return 3.479 - 0.516 * int(word)
    # Grammatical classes, keeping capitalization and leading-space effects.
    if lower == 'the':
        return -5.791 if capital else -0.783
    if lower in {'a', 'an'} and (spaced or capital):
        return -0.261
    if lower in {'this', 'these'}:
        return -15.883 if capital else -1.93
    if lower == 'that':
        return -7.926 if capital else -2.641
    if lower == 'it':
        return -5.642 if capital else -0.43
    if lower in {'he', 'she', 'they', 'we'}:
        return -1.818 if capital else -0.55
    if lower == 'you':
        return 3.84
    if word == 'I':
        return -0.841 if spaced else 1.275
    if lower in {'my', 'our', 'your', 'his', 'her', 'their', 'its'}:
