OUTPUT_NAMES = {'cat', 'ls', 'print', 'printf', 'println'}

@lru_cache(maxsize=32768)
def lexical(s):
    stripped = s.strip()
    word = stripped.lstrip('._-')
    frequency = (zipf_frequency(word.lower(), 'en')
                 if word.isascii() and word.isalpha() else 0.0)
    return stripped, word, frequency


def predict(s, previous):
    stripped, word, frequency = lexical(s)
    if not previous:
        if not stripped.isalpha():
            return 0.058
        return 0.277 if frequency <= 5 else 0.145

    # String operations, type tests/casts, and logical symbols.
    if stripped == '_replace' and previous.strip() == 'str':
        return -0.79
    if word == 'isinstance':
        return -0.57
    if stripped == '_cast':
        return -0.51
    if stripped == '&&':
        return -0.33
    if stripped in {'==', '==='}:
        return -0.125
    if stripped in {'!=', '!=='}:
        return 0.034
    if stripped == '\\\\':
        return -0.174
    if (stripped.lower() in OUTPUT_NAMES and not s[:1].isspace()
            and previous.endswith(QUOTES)):
        return -0.55

    if previous.endswith(QUOTES):
        if not previous.startswith(' '):
            return -0.039
        if previous.endswith('`'):
            return -0.021 if len(stripped) <= 1 else -0.252
        if frequency > 6 and not word[:1].isupper():
            return -0.265
        return -0.070
    if re.search(r'[a-z][A-Z]', stripped):
        return -0.079
    return -0.002


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != document else carry[1]
    s = prefix.token_strings[-1]
    return (document, s), float(predict(s, previous))

"""A short-fragment detector for the nan/nam spelling family.

It also recognizes 南 (south), its compounds and English south words.
Across token boundaries, n + an/am is strongest when both fragments are
short; long word endings and escaped newlines are weaker. Kana readings
use the same nan/nam pattern. Parent-directory paths and NUL bytes are
separate triggers. Small exceptions cover 难/難 (difficult), middle dots,
and N followed by 2 (negative). Whole nan/nam-related names get fixed levels.
These are approximations, not a complete lexical table.
"""
import re
import regex
from anyascii import anyascii
from functools import lru_cache

READS = ()

@lru_cache(maxsize=20000)
def romanize(text):
    return text if text.isascii() else anyascii(text)


def response(text, previous, before_previous):
    if '\x00' in text:
        return 1.3
    if '../' in text:
        if previous.strip() in ('from', '#include'):
            return 6.8 if "'" in text else 4.2
        if '(' in text:
            return 2.8
        return 3.8 if text == '../' else 1.6
    if text == '南':
        return 7.0
    if text == '指南':
        return 5.0
    if '南' in text:
        return 3.5 if text.startswith('南') else 2.0
    if text in ('难', '難'):
        return 2.7
    if regex.search(r'\p{Script=Han}', text):
        return 0.0
    if re.fullmatch(r'\s*[Ss]outhern', text):
        return 2.1
    if re.fullmatch(r'\s*[Ss]outh', text):
        return .2
    if text == '2' and previous.strip() == 'N':
        return -1.8
    if text == '··':
        return .8

    current = romanize(text)
    prev = romanize(previous)
    word = current.strip(' _')
    lower = word.lower()
    if text.strip() == 'нам':
        return .08
    if text == 'نان':
        return 2.0
    if previous.endswith('ن') and text.startswith(('ان', 'ام')):
        return 5.0
    if lower in ('nan', 'nam'):
        if word == 'NaN':
            return .4
        if word[0].isupper():
            return 5.2
        return 2.4 if current.startswith(' ') else 3.5
    if re.fullmatch(r'\.?[Nn]an', current):
        return .9
    if lower in ('nano', 'nancy', 'nathan'):
        return 1.2
    if word == 'NAND':
        return 4.7
    if lower in ('enan', 'anan'):
        return 2.8

    # A literal backslash-n denotes a newline, not a nan syllable.
    escaped = previous.endswith('\\n') or (
        previous == 'n' and before_previous.endswith('\\')
    )
    if regex.search(r'\p{Script=Thai}', text):
        return 0.0
    if not escaped and current and not current[0].isspace():
        if prev.lower().endswith('n'):
            length = len(prev.strip(' _.,/'))
            strength = 1.0 if length <= 3 else .75 if length == 4 else .1
            tail = current.lower()
            if tail.startswith(('an', 'am')):
                size = len(tail)
                value = 5.8 if tail.startswith('an') else 3.2
                value *= 0.55 ** max(0, size - 2)
                if prev.strip(' _.,/') == 'N':
                    value *= 1.5
                if regex.search(r'\p{Script=Cyrillic}', text):
                    value *= .75
                elif not text.isascii():
                    value *= .35
                return value * strength
            if tail.startswith('arn'):
                return 4.0 * strength
            if tail in ('ay', 'au'):
                return 1.0 * strength
            if tail == 'on':
                return .4 * strength
        if prev.lower().endswith('na') and (
            regex.search(r'\p{Script=Katakana}|\p{Script=Hiragana}', text)
            or text == 'ń'
        ):
            if current.lower().startswith(('n', 'm')):
                return 3.2
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before_previous = '', ''
    else:
        _, previous, before_previous = carry
    text = prefix.token_strings[-1]
    value = response(text, previous, before_previous)
    return (doc, text, previous), float(value)

"""Approximate the component by a lexicalized document-opening pulse.

Training spikes concentrate on the opening token (also at truncated row
starts). Repeating that token prolongs the pulse. Lowercase continuations
and control-flow words tend to have larger pulses than sentence openers.
These broad classes leave some token-specific variation unexplained.
After the opening, retain only small conditional/operator/escape responses.
"""
import builtins

READS = ()
BUILTINS = frozenset(dir(builtins))
LOOPS = {'if', 'elif', 'unless', 'for', 'while', 'foreach'}
PRONOUNS = {'I', 'We', 'You', 'He', 'She', 'It', 'They'}
COPULA = {'is', 'are', 'am', 'was', 'were', 'be', 'been', 'being'}
DEMONSTRATIVES = {'This', 'That', 'These', 'Those', 'There'}
CONTROL_AND_DECLARATION = {
    'return', 'try', 'catch', 'except', 'finally', 'throw',
    'switch', 'case', 'else', 'def', 'class', 'func', 'function',
}


def opening_pulse(text):
    word = text.strip()
    gap = text.startswith((' ', '\t'))
    if not word:
        if text and set(text) == {'\r'}:
            return -6.1
        if text and set(text) == {'\t'}:
            return 6.6
        if '\n' in text:
            return 2.7
        return -0.1 if len(text) <= 2 else 2.0
    if word.startswith('<|'):
        return 2.1
    if word.isdigit():
        return 3.1
    if word in LOOPS:
        return 20.0
    if word in {'when', 'whenever', 'until'}:
        return 11.0
    if word in BUILTINS and word[0].islower():
        return 11.0
    if word in {'import', 'package', 'using', 'include'}:
        return 1.5
    if word in CONTROL_AND_DECLARATION:
        return 8.5
    if word in COPULA:
        return 2.1
    if word == 'the':
        return 3.8 if gap else 1.1
    if word in {'a', 'an'}:
        return 6.5 if gap else 5.1
    if word == 'The':
        return 2.2 if gap else -1.2
    if not gap and (word in PRONOUNS or word in DEMONSTRATIVES):
        return 0.3
    if word[0].islower():
        return 5.3 if gap else 4.3
    if word[0].isupper():
        return 5.0 if gap else 3.1
    if word.startswith(('.', '_')) and any(c.isalpha() for c in word):
        return 7.5
    if word.startswith(('#', '-')):
        return 0.3
    return 3.4 if any(c.isalpha() for c in word) else 2.7


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        first_token, opening, blank_line = token, True, True
    else:
        _, first_token, opening, blank_line = carry
        opening = opening and token == first_token
    # A uniform opening run still has only the initial token as context.
    if opening:
        value = opening_pulse(text)
    elif text.strip() in {'if', 'elif', 'unless'} and blank_line:
        value = 0.55
    elif text.strip() in {'&&', '||', '∧', '∨'}:
        value = 0.4
    elif '\\\\' in text:
        value = -0.45 if text.startswith(' ') else 0.5
    else:
        value = 0.0
    if '\n' in text:
        blank_line = not text.rsplit('\n', 1)[1].strip()
    else:
        blank_line = blank_line and not text.strip()
    return (doc, first_token, opening, blank_line), value

"""Opening-text pulses, especially the second digit of an initial '12'.

Approximate the small background by zero and model the larger opening
responses: escapes, indentation, code delimiters and graphic filler. Ordinary
opening words use a length/case heuristic. A few recognizable opening pairs
(number 12, title/date headers, a JavaScript function and a San Francisco
prefix) have their own pulses. Two Thai spelling endings and colon columns
in C banners are additional local patterns. Initial identical-token runs
keep their opening response. Reset all opening state at document boundaries.
This leaves most word-specific background variation unexplained.
"""
import math

READS = ()


def opening(s):
    # Literal text-opening conventions, not token IDs.
    if s == ' .':
        return 2.45
    if s == '\x00':
        return 2.93
    if s in ('\\"', '\\t'):
        return 2.21
    if s == '\\n':
        return 1.42
    if s == '.\\':
        return 1.84
    if s == '<|endoftext|>':
        return 2.65
    if s.startswith('<|'):
        return -0.116
    if s.startswith('/*'):
        return 1.20
    if s.startswith('"""'):
        return 1.28
    if s == 'public':
        return 2.73
    # Repeated typographic/ASCII-art fill marks at the opening.
    if s == '··':
        return 3.47
    if len(s) >= 4 and len(set(s)) == 1 and s[0] in '^█':
        return 3.55
    if s == '1':
        return -0.046
    if s == '\t':
        return 0.82
    if s == '   ':
        return -0.69
    t = s.strip()
    if t.isalpha():
        value = 0.08 + 0.175 * math.log1p(len(t))
        if t.islower():
            value -= 0.07
        if s.startswith(' '):
            value -= 0.085
        if len(t) == 1:
            value += 0.07
        return value
    return 0.15


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, first, repeated, previous = 0, s, True, ''
    else:
        _, position, first, repeated, previous = carry
        position += 1
        repeated = repeated and s == first
    value = opening(s) if repeated else 0.0
    if position == 1 and first == '1' and s == '2':
        value = 4.366
    elif position == 2 and first == '1' and previous == s == '2':
        value = 1.914
    elif position == 1 and first == 'Title' and s == ':':
        value = -2.658
    elif position == 1 and first == '(function' and s == ' ()':
        value = 5.92
    elif position == 1 and first == 'Posted' and s == ' on':
        value = 3.70
    elif position == 1 and first == 'SAN' and s == ' FR':
        value = 2.97
    elif first.startswith('/*') and s == ' ::::::::':
        # Decorative colon columns in a C source-file banner.
        value = -1.22
    if s in ('น', '\ufffd'):
        # Join bytes so a split Thai tone mark is recognized correctly.
        tail = b''.join(prefix.token_bytes[-min(position + 1, 4):])
        text = tail.decode('utf8', 'ignore')
        if text.endswith('ขั้น'):  # Thai step/level; also begins "minimum".
            value = 1.53
        elif text.endswith('ปลั๊'):  # Beginning of the Thai word for "plug".
            value = 1.12
    return (doc, position, first, repeated, s), value

"""Detect short spelling pieces completing ni+k/c, versus ni/nu+g.

The spelling may cross a token boundary. Short nik pieces are strongest;
longer inflected pieces, nic/nich, and a bare ni give weaker negatives.
The opposite, positive pattern is nig/nug, mainly split across tokens.
Transliteration extends the spelling rules to Cyrillic and Arabic alphabets.
East Asian dictionary readings are not treated as alphabetic spellings.
Frequent whole words are downweighted. A short negative suffix trace, a small
document-opening baseline, and repeated middle dots complete the prediction.
"""
import re
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency
import regex

READS = ()


@lru_cache(maxsize=8192)
def spelling(raw):
    east_asian = (r'[\p{Script=Han}\p{Script=Hiragana}'
                  r'\p{Script=Katakana}\p{Script=Hangul}]')
    alphabets = (r'[\p{Script=Latin}\p{Script=Cyrillic}'
                 r'\p{Script=Arabic}\p{Script=Greek}]')
    if regex.search(east_asian, raw):
        return '\x00'
    if any(c.isalpha() for c in raw) and not regex.search(alphabets, raw):
        return '\x00'
    # Dotless Turkish ı is a different vowel from i.
    raw = raw.replace('ı', '\x00').replace('ي', 'i').replace('ق', 'k')
    return anyascii(raw).lower()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    _, previous, last, trace = (doc, '', '', 0.) if fresh else carry
    opening = fresh or last == '<|endoftext|>'
    cur = spelling(raw)
    text = previous + cur
    boundary = len(previous)
    onset = boundary + len(cur) - len(cur.lstrip())
    cyrillic = bool(regex.search(r'\p{Script=Cyrillic}', raw))
    value = 0.
    next_trace = 0.

    hard = [m for m in re.finditer(r'ni(ch|ts|c|k(?!h))', text)
            if m.end() > boundary]
    soft = [m for m in re.finditer(r'n(i|u|ei|ie)g', text)
            if m.end() > boundary]
    if hard:
        m = min(hard, key=lambda m: (m.start() > onset, m.start()))
        ending = m.group(1)
        tail = text[m.end():]
        if m.start() < boundary:
            if ending == 'k':
                value = -6. if len(last.strip()) <= 2 else -3.2
                if boundary - m.start() >= 2:
                    value = -8. if len(spelling(last).strip()) <= 2 else -4.5
            elif ending == 'c':
                value = -3. if tail[:1] in ('k', 't', 'z') else -1.7
            else:
                value = -1.4
            if tail and not cyrillic:
                value *= 0.8
        elif m.start() == onset:
            value = {'k': -5.8, 'c': -3., 'ch': -2.5, 'ts': -3.5}[ending]
            if tail:
                if cyrillic:
                    value *= 0.65 if len(tail) <= 2 else 0.25
                    if zipf_frequency(raw.strip(), 'ru') > 4.5:
                        value *= 0.1
                elif not raw[:1].isspace() and ending == 'c' and tail == 'k':
                    value = -5.5
                else:
                    value = -0.25
        # In the Russian verb stem voznik-, nik is not a nominal suffix.
        if previous.endswith('voz') and m.start() == boundary:
            value *= 0.2
        if regex.search(r'\p{Script=Greek}', raw):
            value *= 0.4
        if value < -1.:
            next_trace = 0.25 * value
    elif soft:
        m = min(soft, key=lambda m: (m.start() > onset, m.start()))
        if m.start() < boundary and len(cur) <= 5:
            value = 4.2 if m.end() == len(text) else 3.3
            if last.strip().lower() == 'n' and cur == 'ig':
                value = 6.
        elif m.start() >= boundary and len(cur.strip()) <= 5:
            if zipf_frequency(raw.strip(), 'en') < 4.:
                value = 3.
    elif raw in ('ニ', '니'):
        value = -0.6
    elif text.endswith('ni') and len(cur.strip()) <= 3:
        accented = (bool(regex.search(r'\p{Script=Latin}', raw))
                    and not raw.isascii())
        value = -1.4 if accented else -0.35
    elif trace and cur.isalpha() and len(cur) <= 4:
        value = trace

    if opening and value == 0. and not raw.startswith('<|'):
        value = 0.3 if regex.search(r'\p{Script=Latin}', raw) else 0.1
    if len(raw) > 1 and set(raw) == {'·'}:
        value = 0.74
    return (doc, text[-6:], raw, next_trace), value

"""Approximate local formatting and small-number responses.

An isolated ASCII space is positive after ASCII whitespace or an escaped
newline, more strongly near the document start. Nonbreaking-space runs and
a following double backtick also activate. Digits 1 and 0 respond to local number
endings (especially 11/21/31 and 30), less strongly in longer numbers.
Fullwidth digits use the same rules with twice the response.
1 immediately after a newline is also positive. End-of-text is positive,
while tokens made of multiple middle dots are negative. Other tokens are zero.
These rules summarize observed local effects, not general sentence meaning.
"""
import math
import unicodedata
from atoms import FULLWIDTH_DIGITS

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail, number, age = '', '', '', 0
    else:
        _, previous, tail, number, age = carry
    token = prefix.token_strings[-1]
    wide = token in FULLWIDTH_DIGITS
    digit = str(unicodedata.decimal(token)) if wide else token
    last_digit = (str(unicodedata.decimal(previous))
                  if previous in FULLWIDTH_DIGITS else previous)
    value = 0.0
    if len(token) >= 2 and set(token) == {'·'}:
        value = -2.43
    elif token == ' ':
        if previous and set(previous) <= set(' \t\r\n'):
            if previous == ' ':
                value = 1.3
            elif '\n' in previous or '\r' in previous:
                value = 0.85
            else:
                value = 1.65 + 0.65 * math.exp(-age / 120)
                if len(previous) == 4:
                    value += 0.4
                elif len(previous) > 4:
                    value = 1.4
        elif tail.endswith('\\n'):
            value = 1.4
        elif tail.endswith(('\n', '\r')):
            value = 0.85
    elif token == '\xa0':
        if previous and previous.isspace() and '\xa0' in previous:
            width = len(previous) + 1
            if width % 4 == 0:
                value = 2.3
            else:
                value = 1.2 if width <= 3 else 0.3
    elif token == '``' and previous == '\xa0':
        value = 1.25
    elif digit == '1':
        if last_digit in ('1', '2', '3'):
            value = 1.0 if len(number) == 1 else 0.4
            if number.endswith('11'):
                value = -0.1
        elif last_digit == '0':
            value = -0.1
        elif last_digit in ('4', '5', '6', '7', '8', '9'):
            value = 0.2 if len(number) == 1 else 0.1
        elif tail.endswith(('\n', '\r', '\\n')):
            value = 0.65
    elif digit == '0':
        if last_digit == '3':
            value = 1.4 if len(number) == 1 else 0.5
        elif last_digit == '0' and len(number) == 1:
            value = 0.15
    elif token == '<|endoftext|>':
        value = 0.85
    if wide:
        value *= 2.0
    number = (number + digit)[-16:] if digit.isdigit() else ''
    return (doc, token, (tail + token)[-80:], number, age + 1), value

"""Approximate an is/ys/iz spelling feature, including i-to-s token boundaries.

Transliteration makes the spelling rule usable across scripts. Extra letters,
common merged words and title-case fragments weaken it; preceding letters and
script adjust its size. Uniform prefixes of dot-pair or carriage-return tokens
have separate positive levels. This is not a dictionary of exceptional words.
"""
import re
import regex
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=32768)
def spelling(text):
    roman = anyascii(text).lower()
    return roman, roman.strip()


def activation(text, previous, uniform):
    if uniform and text and set(text) == {'·'} and len(text) > 1:
        return 1.86
    if uniform and text == '\r':
        return 4.93
    roman, word = spelling(text)
    prev = spelling(previous)[0]
    last = prev[-1:]
    if not word.isalpha():
        return 0.0
    space = roman != word
    match = re.search(r'[iy][sz]', word)
    if match:
        before, after = match.start(), len(word) - match.end()
        factor = 0.38 if word[match.end()-1] == 'z' else 1.0
        if word[match.start()] == 'y':
            factor *= 0.8
        if after:
            factor *= 0.8 if word[match.end():] == 's' else 0.55 / after
        if before == 0 and not space:
            if text[:1].isupper():
                factor *= 0.65 if text.isupper() else 0.12
            bare = bool(re.fullmatch(r'[iy]ss?', word))
            if last and last in 'rl':
                size = 2.7 if bare else 0.92
            elif last and last in 'aeiouy':
                size = 0.43 if bare else 0.25
            elif last.isalpha():
                size = 1.86 if bare else 1.1
            else:
                size = 0.07 if bare else 1.34
            return -size * factor
        factor /= 1.0 + max(0, len(word)-3) * 0.7
        frequency = zipf_frequency(word, 'en')
        factor *= max(0.03, min(1.0, (4.5-frequency)/2.0))
        return -(0.57 if space else 0.64) * factor

    kana_or_hangul = (word in {
        'su', 'si', 'shi', 'shu', 'sho', 'zu', 'seu', 'ssu', 'sshu', 'ssho'
    } and regex.search(r'[\p{Script=Katakana}\p{Script=Hangul}]', text))
    s_unit = word in {'s', 'ss', 'z', 'sh', 'zh', 'si', 'sa', 'su'}
    if not (s_unit or kana_or_hangul) or not word.startswith(('s', 'z')):
        return 0.0
    if space and prev.strip() not in {'i', 'y'}:
        return 0.0
    # Eta also transliterates to i; the rule here is iota-like spelling.
    if not last or last not in 'iy' or previous.endswith(('η', 'ή')):
        return 0.0
    factor = 0.4 if word.startswith('z') else 1.0
    if previous.endswith(('υ', 'ύ')):
        factor *= 0.3
    if not (word.startswith('ss') or word in {'sh', 'zh'}):
        if text.isascii():
            factor /= len(word)
        elif len(text) > 1:
            factor /= len(text)
    if kana_or_hangul:
        if not regex.search(r'[\p{Script=Katakana}\p{Script=Hangul}]', previous):
            return 0.0
        size = 3.57
    elif regex.search(r'\p{Script=Han}', text):
        size = 1.08
    else:
        size = 1.95 if text.isascii() else 1.58
    if prev.endswith(('ri', 'ni', 'li', 'ry', 'ny', 'ly')):
        factor *= 1.7
    if len(prev) > 2 and prev[-2] in 'aeou':
        factor *= 0.5
    return -size * factor


def step(carry, prefix, upstream):
    doc, text = prefix.document_ids[-1], prefix.token_strings[-1]
    same_doc = carry is not None and carry[0] == doc
    previous = carry[1] if same_doc else ''
    uniform = not same_doc or (carry[2] and previous == text)
    return (doc, text, uniform), float(activation(text, previous, uniform))

"""A small lexical mixture, not a single semantic detector.

Recognize a few unusually strong word/phrase completions, with weaker
responses to code syntax, answers and temporal/comparison vocabulary.
At a document start, character fragments and ordinary function words have
separate defaults, retained while one token repeats without interruption.
State resets at each document boundary. Symbol spikes are restricted to
unmixed document openings: the same symbols were weak in other contexts.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

DURATION_UNITS = {
    'second', 'minute', 'hour', 'day', 'week', 'month', 'year',
}
COMPARISONS = {'same', 'different', 'equal', 'either'}
ANSWERS = {'answer', 'result', 'solution', 'response', 'error', 'root'}
SUBJECT_PRONOUNS = {'i', 'you', 'he', 'she', 'it', 'we', 'they'}
POSSESSIVES = {'my', 'your', 'his', 'her', 'our', 'their'}
PREPOSITIONS = {
    'in', 'at', 'to', 'by', 'from', 'with', 'as', 'for', 'of',
}
COPULAS = {'is', 'are', 'was', 'were'}


def initial_value(s):
    w = s.strip()
    low = w.lower()
    if len(s) > 1 and set(s) == {'·'}:
        return 1.07
    if len(s) >= 4 and len(set(s)) == 1 and s[0] in '^█':
        return 1.8 if s[0] == '^' else 2.4
    if s == ' ""':
        return 1.65
    if s == '<|im_start|>':
        return 0.24
    if s == '<|endoftext|>':
        return 1.57
    if not w:
        return 0.5 if '\t' in s else 0.37 if '\n' in s else 0.07
    if low in {'a', 'an', 'the'}:
        return 0.18
    if low in SUBJECT_PRONOUNS:
        return -0.37
    if low in POSSESSIVES or low in COPULAS:
        return 0.38
    if low in PREPOSITIONS:
        return -0.28
    if w.isascii() and w.isalpha() and len(w) == 1:
        return 0.38
    if w.isdigit():
        return 0.30
    if w.isascii() and w.isalpha():
        frequency = zipf_frequency(w, 'en')
        if w.istitle() and frequency < 6:
            return 0.16
        return 0.18 if frequency < 3 else -0.03
    if '_' in s:
        return 0.27
    return 0.13


@lru_cache(maxsize=32768)
def ordinary_value(s):
    w = s.strip().lower()
    singular = w[:-1] if w.endswith('s') else w
    if s == '</tool_call>':
        return 0.10
    if w == 'import':
        return 0.09
    if w in {'public', 'const'}:
        return 0.065
    if s == '::':
        return -0.055
    if w in {'&&', '||'}:
        return 0.065
    if w in COMPARISONS:
        return -0.065
    if singular in DURATION_UNITS or w == 'times':
        return -0.04
    if singular in ANSWERS:
        return 0.065
    if w in {'before', 'later'}:
        return 0.075
    if w == 'during':
        return -0.06
    if w in {'positive', 'correct', 'effective', 'available'}:
        return 0.08
    if w in {'surface', 'floor', 'field', 'direction', 'length'}:
        return 0.08
    return 0.003


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    tail = '' if first else carry[1]
    s = prefix.token_strings[-1]
    initial_run = first or (carry[3] and s == carry[2])
    w = s.strip().lower()
    value = initial_value(s) if initial_run else ordinary_value(s)
    before = tail.lower()
    if w in {'ment', 'ments'} and before.endswith('endorse'):
        value = 1.0
    elif w == 'al' and before.endswith('revers'):
        value = -0.95
    elif w == 'heet' and before.endswith('works'):
        value = 0.85
    elif w == 'for' and re.search(r'\bsolve$', before):
        value = -0.65 if tail.endswith('Solve') else -0.40
    elif w in {'operator', 'operators'} and re.search(
        r'\b(position|momentum|evolution|vertex|spin|hamiltonian)$', before
    ):
        value = -1.1
    elif w == 'solution' and before.endswith('parts water'):
        value = -0.9
    elif w == 'of' and re.search(r'\b(number|set)$', before):
        value = -0.10
    elif w == 'to' and re.search(r'\b(want|going)$', before):
        value = -0.10
    elif w == 'for' and re.search(r'\b(look|looking|search)$', before):
        value = 0.17
    elif s in {'.util', '.math', '.text', '.net'} and before.endswith('java'):
        value = 0.28
    elif s == '.com' and before.endswith('github'):
        value = -0.30
    elif s == '交易所' and before.endswith('证券'):
        value = 0.8
    return (doc, (tail + s)[-64:], s, initial_run), value

"""Sentence and quotation boundaries, rather than every newline.

A period at a line break is strongest on a first or long line, and much
weaker on short, closely spaced lines. Opening a quotation after a sentence
or a speech-introducing colon is another positive case. Source-file line
numbers have a separate colon-and-first-digit response. Most lexical
background variation is deliberately omitted.
"""
import re

READS = ()
_SOURCE_END = re.compile(
    r'\.(?:py|js|jsx|ts|tsx|go|c|cc|cpp|h|hpp|java|rb|rs|php|cs|swift|kt|scala|sh)$'
)
LINE_SLOPE = 0.001
LINE_THRESHOLD = 90
LINE_MAX = 0.34
FIRST_SINGLE = 0.40
FIRST_DOUBLE = 0.27

_SENTENCE_END = re.compile(r'[.!?。]["”’\']*\s*$')
_SPEECH_END = re.compile(r'\b(?:said|says|told|added|asked|replied|wrote):\s*$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, line, seen_break, position, location = '', '', False, 0, False
    else:
        _, tail, line, seen_break, position, location = carry
    token = prefix.token_strings[-1]
    value = -0.003
    stripped = token.strip()
    if stripped == '.':
        value = -0.02
    if '\n' in token:
        before = (line + token.split('\n', 1)[0]).rstrip()
        strength = min(
            LINE_MAX, max(0.01, (len(before) - LINE_THRESHOLD) * LINE_SLOPE)
        )
        if not seen_break:
            strength = FIRST_SINGLE if token.count('\n') == 1 else FIRST_DOUBLE
            if position == 0:
                strength = -0.25
        end = before.rstrip('\"”’\'')
        if end.endswith('.'):
            value = strength
        elif end.endswith('。'):
            value = 0.13
        elif before.endswith('!'):
            value = strength * 0.3
        elif before.endswith(':'):
            value = -0.03
        else:
            value = -0.01
    typographic = token.lstrip().startswith(('“', '«'))
    opening = typographic
    if token.lstrip().startswith('"') and line.count('"') % 2 == 0:
        opening = True
    if token.lstrip().startswith("''") and line.count("''") % 2 == 0:
        opening = True
    speech = bool(_SPEECH_END.search(tail))
    if opening and (_SENTENCE_END.search(tail) or speech):
        value = 0.70 if typographic else 0.50
        previous_line = tail.rstrip().rsplit('\n', 1)[-1]
        if len(previous_line) < 100:
            value *= 0.45
        if speech:
            value = 0.75
    if token == ':' and _SOURCE_END.search(tail):
        value, location = 0.55, True
    elif location:
        if token.isdigit():
            value = 0.21
        location = False
    tail = (tail + token)[-400:]
    if '\n' in token:
        line = token.rsplit('\n', 1)[-1]
        seen_break = True
    else:
        line = (line + token)[-600:]
    return (doc, tail, line, seen_break, position + 1, location), value

"""Short Slavic front-vowel fragments, sensitive to the preceding consonant.

The main positive response is to Russian и/е endings and short и syllables.
These fragments usually receive negative values after velars or hushers.
A weaker Latin-script rule recognizes i fragments, with a recent accented
Slavic letter raising their response. Distinctive non-Russian Cyrillic
letters attenuate the Russian rules: и need not soften consonants there.
Russian comparison words and ни have separate positive responses. Everything else is near zero.
"""
import re

READS = ()
# Columns: other preceding letters, ordinary consonants, velars, hushers.
FRONT_ENDINGS = {
    'и':  (-0.3, 1.9, -1.9, -0.2),
    'им': (-0.2, 1.7, -1.0, -0.3),
    'их': (-1.4, 1.2, -1.5, -0.5),
    'ий': (0.0, 0.7, -0.8, -0.6),
    'ие': (0.0, 0.5, -1.2, -0.2),
    'ей': (-0.5, 1.4, -0.2, -1.0),
    'ее': (-0.3, 1.6, 0.0, -1.0),
}
COMPARISONS = {
    'более': 1.8, 'наиболее': 3.4, 'дальше': 2.5, 'лучше': 0.8,
}
SMALL_SOFT_FORMS = {
    'ю': 0.3, 'я': 0.3, 'ь': 0.3, 'й': 0.3,
    'ня': 0.3, 'ью': 0.6, 'ить': 0.1, 'ите': 0.4,
}
SLAVIC_ACCENTS = set('ąćęłńóśźżčďěňřšťůýž')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, accent_age, foreign_age = '', 0, 0
    else:
        _, previous, accent_age, foreign_age = carry
    token = prefix.token_strings[-1]
    t = token.lower()
    p = previous[-1:].lower()
    accent_age = max(0, accent_age - 1)
    if any(c in SLAVIC_ACCENTS for c in t):
        accent_age = 40
    foreign_age = max(0, foreign_age - 1)
    # Russian ъ occurs only before е/ё/ю/я; other uses suggest Bulgarian.
    recent = (previous[-1:] + t).lower()
    if (any(c in 'іїєґўјћђљњџќѓѕ' for c in t)
            or re.search('ъ[^еёюя]', recent)):
        foreign_age = 160
    elif any(c in 'ыэё' for c in t):
        foreign_age = 0
    value = 0.0
    if t != t.strip():
        if t.strip() in COMPARISONS:
            value = COMPARISONS[t.strip()]
        elif t.strip() == 'ни':
            value = 2.3
        elif t == ' и':
            value = -0.12
    else:
        if t in FRONT_ENDINGS:
            kind = (1 if p and p in 'бвдлмнпрстфзц' else
                    2 if p and p in 'гкх' else
                    3 if p and p in 'жчшщ' else 0)
            value = FRONT_ENDINGS[t][kind]
            if kind == 1 and len(previous.strip()) == 1:
                value += 0.5 if t == 'и' else -0.1
        elif re.fullmatch('[аея]?[бвгджзклмнпрстфхцчшщ]и', t):
            c = t[-2]
            value = (1.5 if c in 'днрт' else
                     1.3 if c in 'бвпф' else
                     0.5 if c == 'м' else
                     0.25 if c == 'л' else
                     0.4 if c in 'сзц' else -0.1)
            if previous.strip().lower() == 'п':
                value -= 0.6
        elif t in ('нее', 'ней'):
            value = (-0.5 if p and p in 'нд' else
                     0.6 if p and p in 'жчшщ' else 2.4)
        elif t in SMALL_SOFT_FORMS:
            value = SMALL_SOFT_FORMS[t]
        elif t in ('i', 'ie', 'ier', 'ich', 'im', 'í', 'iej'):
            if p == 'k':
                value = -1.2
            elif p == 'g':
                value = -0.1
            elif t == 'í':
                value = 0.3
            elif accent_age:
                value = 0.3
        elif t in ('ki', 'kie', 'gi'):
            value = -0.3
        elif t in ('ni', 'ri', 'ti', 'mi', 'si', 'ci', 'ní', 'tí', 'ń', 'ň'):
            value = 0.5 if accent_age else 0.0
    if foreign_age and re.search('[а-яё]', t):
        value *= 0.1
    return (doc, token, accent_age, foreign_age), value

programs.haiku:
"""Component layers.1.mlp.down_proj:3097: the Slavic "syllable-final и" detector.

It fires on the vowel и (and Latin i) when it follows a consonant inside a word, as
in ви-да, тради-ция, спаси-бо, Ро-ди-он, and on the endings -им -ей -их -ий -ие that
begin with the same vowel. Its sign depends on the consonant before the vowel:
  * after most consonants (н р в д п б з с ф т м) it is positive, strongest after б п в д;
  * after ж ч ш щ it is about zero;
  * after the velars к г х (and Polish k) it is negative: the plural and case endings
    of nouns and adjectives (ноги, реки, дороги, блоги, Polish -ki, -kie).
A bare consonant+и syllable inside a longer piece (ни, ри, ти, ани, ени) is judged
the same way. Comparatives and superlatives (-ней, -нее, ' ни', ' более', ' наиболее')
fire strongly. Everything else is 0. Only the current and previous token are read.
"""

import re

READS = ()

CYRILLIC = re.compile(r"[Ѐ-ӿ]+")
VOWELS = set("аеёиоуыэюяaeiouy")

# Value after the consonant, for a bare и (or Latin i) token, or an ending like им, ей.
AFTER_CONSONANT = {
    "к": -2.0, "г": -1.8, "х": -2.0, "k": -2.0, "g": -0.3,
    "ж": -0.5, "ч": -0.5, "ш": -0.5, "щ": -0.5,
    "л": 1.5, "м": 1.2, "т": 1.4, "ц": 1.3,
    "н": 2.0, "р": 2.3, "в": 2.8, "д": 2.4, "п": 2.6, "б": 3.0,
    "з": 2.2, "с": 2.5, "ф": 1.8,
}
# A word piece ending in и, by the consonant before that и.
SYLLABLE_END_I = {
    "к": -0.1, "г": -0.1, "х": -0.1, "ж": 0.1, "ч": 0.0, "ш": 0.1,
    "л": 0.3, "м": 0.3, "т": 0.7, "ц": 0.3,
    "н": 1.5, "р": 1.4, "в": 1.5, "д": 1.6, "п": 2.0, "б": 1.5,
    "з": 1.0, "с": 0.9, "ф": 0.9,
}
VOWEL_ENDINGS = ("им", "ей", "их", "ий", "ие")
SCALE_ENDING = 0.8
COMPARATIVE_ENDINGS = ("ней", "нее")
COMPARATIVE_WORDS = {" ни", " более", " наиболее"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if len(prefix) > 1 else ""
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = previous[-1].lower() if same_doc and previous else ""
    before_consonant = before != "" and before not in VOWELS

    if token in ("и", "i", "И"):
        return None, AFTER_CONSONANT.get(before, 0.0) if before_consonant else 0.0
    if token in COMPARATIVE_WORDS:
        return None, 1.5
    if token.endswith("ней"):
        return None, 2.5
    if token.endswith(COMPARATIVE_ENDINGS):
        return None, 1.5
    if not CYRILLIC.fullmatch(token):
        return None, 0.0
    if token.startswith(VOWEL_ENDINGS) and before_consonant:
        return None, SCALE_ENDING * AFTER_CONSONANT.get(before, 0.0)
    if token.endswith("и") and len(token) >= 2:
        return None, SYLLABLE_END_I.get(token[-2].lower(), 0.0)
    if token.endswith("ми"):
        return None, 0.4
    return None, 0.0

