"""A lexical waiting/reconsideration signal, with a short conversational echo.

'Wait' is strongest; inflections and hesitation interjections are weaker.
After 'Wait', recognize 'no', a comma, and 'a second'. Also recognize 'hold on'.
A small text tail handles 'Wait' split across tokens. Unrelated tokens get zero;
this intentionally leaves their many small, irregular activations unexplained.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 9)
    _, previous, tail, age = carry
    raw = prefix.token_strings[-1]
    word = raw.strip()
    lower = word.lower()
    age = min(age + 1, 9)
    value = 0.0

    if re.fullmatch(r'waits?', lower):
        value = 1.06 if word[0].isupper() else 0.98
        age = 0
    elif (lower in ('ait', 'it', 't') and
          re.search(r'(?:^|[^a-z])wait$', tail + raw, re.I)):
        value, age = 1.25, 0
    elif lower in ('waiting', 'waited', 'waiter', 'waiters'):
        value = 0.55
    elif re.fullmatch(r'hm{2,}', lower):
        value = 0.33
    elif word in ('Ah', 'Oh', 'Well'):
        value = {'Ah': 0.18, 'Oh': 0.16, 'Well': 0.13}[word]
    elif previous in ('hold', 'hang') and lower == 'on':
        value = 0.52
    elif age <= 2:
        if word == ',':
            value = 0.25
        elif lower == 'no':
            value = 0.43
        elif lower == 'a' and age == 1:
            value = 0.19
        elif lower == 'hold':
            value = 0.30
        elif lower in ('but', 'actually'):
            value = 0.12
        elif lower in ('perhaps', 'maybe', 'let'):
            value = -0.08
    elif age == 3 and previous == 'no' and word == ',':
        value = 0.25
    if age <= 3 and previous == 'a' and lower == 'second':
        value = 0.20
    return (doc, lower, (tail + raw)[-16:], age), value

programs.haiku:
"""layers.1.mlp.down_proj:3102: a document-start component.

What it does, in plain terms: almost everywhere inside a document this MLP output
direction is quiet (typical size about 0.04). The one place it reacts in a readable way
is the first token of a document: the first token of a row, or the first token after a
document break (<|endoftext|>). There the model has no earlier text to look at, so the
component's size depends only on that token. The program predicts a class-level value at
document starts and 0 at every other token:

- non-Latin script (Hangul, kana, Han, Cyrillic, Arabic, Thai, ...): about -0.2;
- a word with no leading space that starts with a lowercase letter: about -0.1;
- a capitalised word: about -0.06;
- a token containing a newline: about +0.2;
- the end-of-text marker itself: about +0.14;
- anything else, and every later token: 0.

These class values are the average sizes measured on training text. Document-start
activations spread widely around them (std about 0.25), so the program is a weak
predictor. Its value is in saying where the component is not silent, not in matching
the bulk of its variance.
"""

READS = ()

# Mean activation at a document's first token, by token class (measured on training text).
START_VALUE = {
    "non_latin": -0.21,
    "word_lower": -0.10,
    "word_capital": -0.06,
    "newline": 0.20,
    "special": 0.14,
}


def token_class(text):
    """A coarse class for one token's text (its decoded string alone)."""
    if text.startswith("<|") and text.endswith("|>"):
        return "special"
    if "\n" in text:
        return "newline"
    body = text.strip()
    if body and not body.isascii():
        return "non_latin"
    if body.isalpha():
        if body[0].isupper():
            return "word_capital"
        return "word_lower" if text[:1] != " " else "word_space_lower"
    return "other"


def step(carry, prefix, upstream):
    """Predict the activation at the newest token of the prefix."""
    t = prefix.position
    starts_document = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not starts_document:
        return carry, 0.0
    value = START_VALUE.get(token_class(prefix.token_strings[-1]), 0.0)
    return carry, float(value)

"""Explains layers.1.mlp.down_proj:3103 with a few token classes.

The component is diffuse: most of its variance sits in a long tail of contexts that
no simple rule captures. What the rules do capture:

- Strongly negative on the leader/fill characters "··" and "⎯" (dot and bar runs).
- Negative at the first token of each document (a document start within a packed row).
- Mildly positive on a parenthesis fused to an identifier, as in code parameters
  ("(order", "(root", "(config").
- Slightly positive on a capitalised word with a leading space (names such as " John",
  " Person", " Speaker").
- Near zero (its mean) elsewhere.
"""

READS = ()

LEADER_FILL = {"··", "⎯"}
DOC_START_VALUE = -0.19
LEADER_VALUE = -1.4
PAREN_IDENT_VALUE = 0.2
CAPITAL_WORD_VALUE = 0.035
BASELINE = 0.008


def _is_paren_identifier(s):
    # "(" immediately followed by letters or underscores: a fused parameter-style token.
    return len(s) > 1 and s[0] == "(" and s[1:].replace("_", "a").isalpha()


def _is_capital_word(s):
    # " Name": a leading space, one capital, then lowercase letters.
    return len(s) > 2 and s[0] == " " and s[1].isupper() and s[2:].islower() and s[2:].isalpha()


def step(carry, prefix, upstream):
    t = prefix.position
    token = prefix.token_strings[t]
    starts_document = t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]
    if starts_document:
        value = DOC_START_VALUE
    elif token in LEADER_FILL:
        value = LEADER_VALUE
    elif _is_paren_identifier(token):
        value = PAREN_IDENT_VALUE
    elif _is_capital_word(token):
        value = CAPITAL_WORD_VALUE
    else:
        value = BASELINE
    return carry, float(value)

programs.sol:
"""A surface-format approximation, strongest at opening quoted content.

Quotes, string-value separators and several code/string openers get positive
values; fused JSON brace/quote openings get negative values. Other rules
recognize tab/space indentation, import-like declarations, and initial 19/20
number prefixes, especially in date or citation contexts. Internal 20 is weak
or negative. Backticks and emphasis markers get small estimates.

Punctuation and quote-parity heuristics use only 240 recent characters. This
is not a full parser. Unrecognized tokens get zero, and documents reset state.
"""
import regex as re
import calendar

MONTHS = set(calendar.month_name[1:]) | set(calendar.month_abbr[1:])
READS = ()


def predict(token, before, java):
    s = token.lstrip()
    line = re.split(r'\n|\\n', before)[-1]
    # Source layout and declaration starts.
    if re.fullmatch(r'\t +', token):
        n = len(token) - 1
        return .32 + .03*n if n < 5 else min(.76, .50 + .017*n)
    if token == '{"':
        return -1.1
    if token == ' {"':
        return -.23
    if s == 'import':
        if token == s and (java or before.rstrip().endswith(';')):
            return 1.75
        return .03
    if s in ('use', 'using') and before.rstrip().endswith(';'):
        return 2.0 if s == 'use' else 1.2
    if token == ' {' and before.endswith('import'):
        return 1.6
    if java and s == 'static' and before.endswith('import'):
        return 2.3
    if s == 'EOF':
        return 1.7 if re.search(r'<<<?\s*[\'\"]?$', before) else -.15
    if token == '\n' and re.search(r'<<<?\s*[\'\"]?EOF$', before):
        return 1.4
    # Completion of an ASCII-escaped UTF-8 left double quote.
    if token == 'c' and before.endswith(r'\xe2\x80\x9'):
        return 2.8
    # Leading digits of modern years, not arbitrary zeros and nines.
    if token in ('0', '9'):
        m = re.search(r'(?<!\d)([12])$', before)
        if m and ((m[1] == '1' and token == '9') or
                  (m[1] == '2' and token == '0')):
            if re.fullmatch(r'\s*\d*', line):
                return .10 if '\t' in before else .25
            context = before[:-1].rstrip()
            if re.search(r'\bet\s+al\.[, (]*$', context, re.I):
                return 1.0
            if re.search(r'\b(in|since|during|until|from|the)$', context, re.I):
                return .95 if token == '9' else .75
            words = re.findall(r'\w+', context[-25:])
            if any(w.capitalize() in MONTHS for w in words):
                return .8
            if re.search(r'\p{Script=Han}$', context):
                return .75
            if context.endswith('('):
                return .8
            if re.search(r'[=.$/:\-]\s*$', context):
                return .0
            return .78 if token == '9' else .35
        if token == '0' and re.search(r'\d+2$', before):
            return -.27
        return 0.0
    # Typographic quotation marks and fused field delimiters.
    if s.startswith(('„', '«')):
        return 1.4 if s.startswith('„') else 1.0
    if s.startswith(('“', '‘', '「', '『')):
        return .55 if token.startswith(' ') else .65
    if s.startswith(('：“', '、“', '。“', '，“', '、「', '。「')):
        return 1.0
    if s in (':"', ':`', '":"'):
        return .5 if s == '":"' else .8
    if s in ("''", '""'):
        return 1.1 if token.startswith(' ') and s == "''" else .35
    # ASCII quoting: values, keys, escapes, and likely closing quotes.
    if s in ('"', "'", '\\"', "\\'"):
        escaped = s.startswith('\\')
        q = s[-1]
        if token.startswith(' ') and escaped:
            return 1.1
        if before.endswith(q + ':') or before.endswith(q + ': '):
            return 1.4 if q == '"' else 1.1
        if q == '"' and re.search(r'"[,]\s*$', before):
            return -.15 if line.rfind('{') > line.rfind('[') else .4
        if escaped:
            stem = before.rstrip('\\')
            raw_prefix = re.search(r'(?<!\w)[frb]$', stem)
            opening = bool(stem) and (
                stem[-1] in '([={:"\',' or stem[-1].isspace() or raw_prefix
            )
            return 1.4 if opening else .25
        if token.startswith(' '):
            if before.rstrip().endswith((':', '=>', '===', '!==')):
                if q == "'":
                    return 1.1
                return -.1 if line.count('"') % 2 else .8
            if q == '"':
                if before.endswith(('.', '?', '!')):
                    return .65
                if len(re.findall(r'(?<!\\)"', line)) % 2:
                    return .07
                boundary = before.endswith(('.', '?', '!', '\n', '<<'))
                return .8 if boundary else .55
            return .65
        if re.search(r'(?<!\w)[rfb]{1,2}$', before):
            return 1.15
        if q == '"' and not line.strip():
            return .7
        return .03
    if s.startswith(('("', "('", '=\"', "='", '(\\"', '=\\"')):
        if s == '="' and len(re.findall(r'(?<!\\)"', line)) % 2:
            return .05
        if token.startswith(' ') or not before:
            return .3
        return 1.05 if '\\' in s else .75
    if s.startswith((',"', ',\'')):
        return 1.15 if re.search(r'\w+\([^"\']*$', line) else .0
    if s == '#"':
        return 2.1
    if s in ('"""', "'''", '"""\n') and token.startswith(' '):
        return 1.0 if before.rstrip().endswith('(') else .15
    if s.startswith('"') and len(s) > 1 and s[1].isalpha():
        return .75 if not line.strip() or before.endswith('f') else .2
    if token == ' `':
        return .25
    if token == ' **':
        return -.6 if line.count('"') % 2 else .3
    if s == '<' and before.rstrip().endswith('include'):
        return 1.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, java = '', False
    else:
        _, before, java = carry
    token = prefix.token_strings[-1]
    value = predict(token, before, java)
    text = (before + token)[-240:]
    if re.search(r'\bpackage [\w.]+;|\bimport [\w.]+;', text):
        java = True
    return (doc, text, java), value

programs.haiku:
"""Where this component (layers.1.mlp.down_proj:3105) fires.

Plain-language rules, checked against the component's own activations:
- an opening quotation mark that starts a string, strongest when it starts a
  value after a colon (`"key": "`), also after an opening bracket; weak after a comma;
  curly, single and escaped opening quotes count the same;
- the '9' of '19' and the '0' of '20' when a year is written in running text, moderate;
- the word 'import' inside a Java-style import block (a ';' in the last ~40 tokens),
  strong; ' static' right after any 'import' also counts;
- a code indent: a tab followed by spaces, moderate;
- the opening of a JSON object that begins with a quote ('{"'), negative.
Everything else is 0.
"""
READS = ()

QUOTES = set("\"'“„«‘『「`")
OPENERS = " ([{=:\t\\"


def _opening_quote(s):
    core = s.lstrip(OPENERS)
    return len(s) > len(core) and len(core) == 1 and core in QUOTES


def _quote_value(prev):
    if prev.endswith(":"):
        return 1.2
    if prev.endswith("("):
        return 1.0
    if prev.endswith(","):
        return 0.3
    return 0.6


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    s = toks[-1]
    p = toks[-2] if len(toks) > 1 else ""
    q = toks[-3] if len(toks) > 2 else ""
    if s == '{"':
        return None, -1.2
    if _opening_quote(s):
        return None, _quote_value(p)
    if s == "9" and p == "1" and not q.isdigit():
        return None, 0.7
    if s == "0" and p == "2" and not q.isdigit():
        return None, 0.4
    if s == "import" and any(";" in x for x in toks[-40:-1]):
        return None, 2.0
    if s == " static" and p == "import":
        return None, 2.0
    if s.startswith("\t") and s[1:].startswith(" "):
        return None, 0.55
    return None, 0.0

programs.sol:
"""Local negation, strongest on mental-state predicates and infinitives.

A short lexical scale distinguishes wanting/thinking from weaker auxiliaries.
Negation can cross one adverb, and a negated verb can carry its pulse onto
`to`. Modal inability weakens mental-state pulses. Other verbs use a small
part-of-speech baseline. Chinese negative markers get a conservative pulse,
stronger when a dictionary identifies a mental state. This is not a parser.
"""
from functools import lru_cache
import wordnet
import cedict
import regex

READS = ()
NEGATION = {'not', "n't", "'t", '’t', 'never', 'cannot', 'cant',
            'dont', 'doesnt', 'didnt', 'without'}
MODIFIERS = {'really', 'necessarily', 'even', 'only', 'just', 'always',
             'ever', 'particularly', 'quite', 'actually', 'exactly'}
# Present-tense mental states, including appearance and perception.
MENTAL = {'want': 7.8, 'think': 6.0, 'like': 4.7, 'seem': 4.7,
          'look': 2.5, 'appear': 2.5, 'believe': 2.2, 'feel': 2.2,
          'know': 0.3, 'understand': 0.3}
TO_COMPLEMENTS = {'want', 'wanting', 'seem', 'appear', 'like', 'going',
                  'able', 'allowed', 'have', 'need', 'likely', 'meant',
                  'intended', 'expected', 'planned'}

@lru_cache(maxsize=8192)
def negated(word):
    if word == 'to':
        return -6.5
    if word in MENTAL:
        return -MENTAL[word]
    if word == 'wanting':
        return -6.3
    if word == 'let':
        return -4.7
    if word in {'going', 'being', 'having', 'looking', 'likely'}:
        return -2.5
    if word in {'be', 'been', 'have', 'has', 'had', 'do', 'does', 'did',
                'can', 'could', 'would', 'should', 'will', 'must', 'may'}:
        return -1.2
    if word in {'allowed', 'yet', 'too'}:
        return -1.4
    pos = wordnet.parts_of_speech(word)
    if 'verb' in pos:
        return -1.5 if word.endswith('ing') else -0.65
    return 0.0

@lru_cache(maxsize=4096)
def chinese_negated(word):
    gloss = ' '.join(cedict.glosses(word)).lower()
    mental = ('to want', 'to think', 'to like', 'to love', 'to wish',
              'to let', 'to allow', 'happy', 'willing', 'pleased')
    return -3.5 if any(term in gloss for term in mental) else -0.6


def mental_scale(auxiliary, negation):
    """Inability and hypothetical negatives are weaker than denial."""
    if auxiliary in {'can', 'couldn'} or negation == 'cannot':
        return 0.3
    if auxiliary in {'won', 'wouldn', 'shouldn'} or negation == 'never':
        return 0.6
    return 1.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        a, b, previous = '', '', ''
    else:
        a, b, previous = carry[1]
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    value = 0.0
    if previous in NEGATION:
        value = negated(word)
        if value < -3 and word not in {'to', 'let'}:
            value *= mental_scale(b, previous)
    elif b in NEGATION and previous in MODIFIERS:
        factor = 0.65
        if previous in {'only', 'just'}:
            factor = 0.1 if word == 'to' else 0.4
        value = factor * negated(word)
    elif word == 'to' and (b in NEGATION or
                          (a in NEGATION and b in MODIFIERS)):
        if previous in TO_COMPLEMENTS:
            value = min(-1.3, 0.8 * negated(previous))
            if value < -3:
                value *= mental_scale(a, b)
    elif word == 'to' and previous in {'unable', 'unlikely'}:
        value = -1.4
    elif previous == 'less' and word == 'likely':
        value = -3.5
    elif previous == 'no' and word in {'longer', 'means'}:
        value = -2.5
    elif previous.endswith(('不', '没', '未', '無', '无')):
        if regex.search(r'\p{Script=Han}', word):
            value = chinese_negated(word)
    if raw == 'Not':
        value = -1.3
    # Hedge the strength of a cue whose full context is not modeled.
    return (doc, (b, previous, word)), 0.9 * value

"""Approximate a document-onset pulse, with coarse token-dependent strength.

Return zero after the first token. At onset, chat markers, indentation and
quotation/escape fragments receive larger pulses; digits and plain punctuation
receive little. Word frequency, case and length approximate lexical variation.
These are broad classes, not a table of individual token responses.
"""
import unicodedata
from wordfreq import zipf_frequency

READS = ()

PREPOSITIONS = frozenset('''
of to in for on with at by from into onto over under about between through
before after during without within upon across against behind beyond near toward
'''.split())


def step(carry, prefix, upstream):
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    if not first:
        return None, 0.0

    text = prefix.token_strings[-1]
    word = text.strip()
    if text.startswith('<|'):
        value = 8.0
    elif text.isspace():
        indent = '\n' not in text and (len(text) > 1 or '\t' in text)
        value = 8.0 if indent else -0.3
    elif word.isdecimal():
        value = -0.6
    elif any(c in text for c in '\"\'\\'):
        value = 5.4
    elif word.lower() in PREPOSITIONS:
        value = -0.4
    elif len(word) == 1 and word.isascii() and word.isalpha():
        value = 0.4 if word.isupper() else 2.6
    elif word.isalpha():
        frequency = zipf_frequency(word, 'en')
        if frequency >= 7:
            value = 0.1
        elif frequency >= 6:
            value = 2.1
        elif word.isascii() and word.isupper():
            value = 2.3
        elif word.isascii() and len(word) == 2:
            value = 3.5
        elif word.isascii() and len(word) >= 6:
            value = 5.5
        else:
            value = 4.5
    elif word and all(not c.isalnum() for c in word):
        closing = any(unicodedata.category(c) == 'Pe' for c in word)
        value = 1.8 if closing else 0.0
    else:
        value = 3.0
    return None, value

"""A sparse, spelling-based approximation of browser-code-associated pulses.

Training peaks cluster around JS/CSS names, HTML tags and inline code.
These rules recognize those spellings, not the text's full meaning. Editor
and front-end vocabulary get weaker responses; ordinary tokens get zero.
Split abbreviations, some Slavic spelling collisions and wholly middle-dot
prefixes are included. A 160-character tail resets at document boundaries.
"""
import re

READS = ()
TAG_STRENGTH = {'script': -11.0, 'style': -8.0, 'link': -4.7}


def response(token, before, dots_only=False):
    word = token.strip()
    bare = word.lstrip('./_-')
    low = bare.lower()
    prev = before[-1:] if before else ''

    if word in ('<script', '<style', '<link'):
        return TAG_STRENGTH[word[1:]]
    if token.startswith('>'):
        if re.search(r'<script\s*$', before):
            return -6.0
        if re.search(r'<style\s*$', before):
            return -2.0

    # A language abbreviation split between tokens, including j-sh spellings.
    if (prev in ('j', 'J', 'й', 'Й')
            and re.fullmatch(r'(?:s[cć]?|S[A-Z]*|ś.*|[шщ](?:[ие].*)?)', token)):
        return -6.5
    if prev.lower() == 'j' and token.startswith('š'):
        return -1.8
    if prev in ('C', 'c') and token in ('ss', 'SS'):
        return -3.6
    if low == 'js':
        if word.startswith('.'):
            if before.lower().endswith('node'):
                return -0.4
            return -4.0
        # Camel-case Js differs from plural initials or numeric units.
        if bare == 'Js':
            if prev.isupper() and token == bare:
                return -0.3
            if prev.isdigit() or token[:1].isspace():
                return -1.6
            return -6.9
        return -4.0
    if low in ('javascript', 'avascript'):
        if re.search(r'(?:href=[\"\']|text/)$', before):
            return -10.5
        return -4.9
    if low == 'css':
        if re.search(r'text/?$', before):
            return -11.0
        if re.search(r'<link[^>]*$', before) or before.endswith('```'):
            return -7.5
        return -3.9
    if low == 'jquery':
        return -3.8
    if token.lower() == 'query' and prev in ('J', 'j'):
        return -8.0

    # Opening tags and the attributes which contain browser-side code.
    if low in ('script', 'style', 'link') and re.search(r'<\s*$', before):
        return TAG_STRENGTH[low]
    if bare == 'stylesheet':
        if re.search(r'<link\s+rel=[\"\']$', before):
            return -9.0
        return -3.0
    if word in ('="', "='"):
        if re.search(r'\bon\w+\s*$', before):
            return -13.5
        if re.search(r'\bstyle\s*$', before):
            return -4.0
    if low == 'src' and re.search(r'<script\s*$', before, re.I):
        return -9.5
    if low == 'href' and re.search(r'<link[^>]*$', before, re.I):
        return -7.0
    if bare in ('onclick', 'onchange', 'onload'):
        return -1.8

    if low == 'frontend':
        return -2.5
    if ((low == 'end' and before.lower().endswith('front'))
            or (low == 'side' and before.lower().endswith('client'))):
        return -7.0
    # Ordinary 'script' differs from HTML script tags.
    if low in ('script', 'scripts', 'cript'):
        if low == 'script' and token[:1].isspace():
            return 0.6
        return -0.4
    if low in ('editor', 'editors'):
        return -1.6 if word[:1] in '_-' else -0.6
    if low == 'escape':
        return -0.3
    if dots_only:
        return -1.15
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_doc = carry is not None and carry[0] == doc
    before = carry[1] if same_doc else ''
    token = prefix.token_strings[-1]
    dots_only = (carry[2] if same_doc else True) and set(token) == {'·'}
    value = response(token, before, dots_only)
    return (doc, (before + token)[-160:], dots_only), value

programs.haiku:
"""Layer 1 MLP down_proj component 3111: a "later item of a sequence" detector.

The component writes a negative value on tokens that name a later item in a list,
pair or sequence, and is near zero elsewhere:
  * digits that number an item, above all a line number at the start of a numbered
    listing ("   78<TAB>"), where 3, 5, 7 and 9 are the most negative; other digits are
    only mildly negative;
  * ordinal and contrast words for the other/later member of a set: "second", "third",
    "another", "else", "others", "other", "right" (vs left), "below"/"bottom" (vs above/top),
    "negative" (vs positive);
  * single-letter variable labels that follow a first one in a pair of symbols: "b", "y",
    "q", "c", "j" (the first symbol is usually "a" or "x").
Everything else predicts 0. Values are in typical activation units (negative = pushes down).
"""

READS = ()

# Digits in a line-number prefix are negative, the odd-looking ones (3, 5, 7, 9) most so.
LINE_NUMBER_DIGIT = {"0": -0.4, "1": -0.36, "2": -0.46, "3": -1.2, "4": -0.6,
                     "5": -1.27, "6": -0.62, "7": -1.04, "8": -0.81, "9": -1.25}
OTHER_DIGIT = -0.12

WORD_VALUES = {
    "second": -1.0, "Second": -1.8, "third": -1.2, "Third": -2.5, "fourth": -0.5,
    "another": -0.7, "else": -0.7, "others": -0.9, "other": -0.3, "right": -0.7,
    "below": -0.5, "bottom": -0.9, "lower": -0.4, "negative": -0.9,
}
LETTER_VALUES = {"b": -0.9, "B": -0.5, "y": -0.7, "Y": -0.8, "q": -0.6, "c": -0.3, "j": -0.3}


def _at_line_number(prefix):
    """True if the newest token is a digit in a line-number prefix: only spaces and digits
    since the last newline, as in a numbered code listing."""
    text = ""
    for s in reversed(prefix.token_strings[-12:]):
        if "\n" in s:
            text = s.split("\n")[-1] + text
            break
        text = s + text
    else:
        return False
    return text.strip().isdigit()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if word.isdigit():
        if word in LINE_NUMBER_DIGIT and _at_line_number(prefix):
            return None, LINE_NUMBER_DIGIT[word]
        return None, OTHER_DIGIT
    if word in WORD_VALUES:
        return None, WORD_VALUES[word]
    if word in LETTER_VALUES:
        return None, LETTER_VALUES[word]
    return None, 0.0

programs.sol:
"""Approximate a standalone full-stop-in-prose signal.

A period after a four-letter-or-longer lowercase word gets a large response.
Shorter words use recent spacing and distance from the last terminal mark
as clues to sentence endings versus dotted fragments. Prior full-stop count
and initial capitalization adjust the strength. Other stop tokens, document
starts, early commas and line breaks receive separate small responses.
"""
import re
from collections import deque

READS = ()


def prose_period(word, gap, spaces, stops, capital_start):
    """Distinguish prose endings from initials and short dotted fragments."""
    if len(word) <= 3:
        if gap <= 10:
            return 0.05
        if spaces <= 14:
            return 0.15
        return 0.67 if word.islower() else 0.31

    if not word.islower():
        return 0.51
    if stops <= 5:
        return 0.49 if capital_start else 0.73
    return 0.84


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, text, recent = 0, '', deque(maxlen=24)
        gap, stops, capital_start = 0, 0, token[:1].isupper()
    else:
        _, position, text, recent, gap, stops, capital_start = carry

    value = -0.003
    if token == '.':
        match = re.search(r'([^\W\d_]+)$', text)
        word = match.group(1) if match else ''
        context = ''.join(recent)
        value = prose_period(
            word, gap, context.count(' '), stops, capital_start)
    elif token == '。':
        value = 0.22 if position <= 101 else 0.42
    elif token in (').', '].', '}.', '`.', '".', "'."):
        value = 0.28
    elif token == ' .':
        value = 0.26
    elif token.strip() == '.' and '\n' in token:
        value = -0.04 if gap <= 5 else 0.07
    elif token == ',' and position <= 110:
        value = -0.14 if capital_start else -0.03
    elif '\n' in token:
        value = -0.02

    if position == 0 and token != '.':
        value = -0.26
    recent.append(token)
    gap = 0 if any(c in token for c in '.。!?') else gap + 1
    stops += token.count('.') + token.count('。')
    carry = (doc, position+1, (text+token)[-80:], recent,
             gap, stops, capital_start)
    return carry, float(value)

programs.haiku:
"""Sentence-final full stop detector for layers.1.mlp.down_proj:3112.

The component writes a positive signal on a full stop that closes an English
sentence, as in "...a standard counterstain method was applied. First, ...".
It is strongest after a lowercase word, and stronger the longer that word is:
about 0.2 per letter up to 0.8 (so "...applied." is high, "...in a." is lower).
After a capitalised word or an abbreviation ("Fig.", "St.", "Mr.") it is weak,
and after a digit ("1.5", "3.0") it is close to zero. The same rule applies to
the Chinese/Japanese full stop 。, and to ")." endings. Other tokens are 0.
The rule looks only at the token and the one before it, which is all the
component can see; it does not model the rest of the context.
"""

READS = ()

ENDINGS = {"。": 0.37, ").": 0.31}  # other sentence-final tokens, mean activations


def full_stop(prev):
    """Activation of a '.' token after the token `prev`."""
    word = prev.strip()
    if not word:
        return 0.2
    if word[-1].isdigit():
        return 0.1
    if word.isalpha():
        if word.islower():
            return min(0.8, 0.2 * len(word))
        return 0.3 if len(word) >= 3 else 0.12
    return 0.18


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == ".":
        prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
        return carry, float(full_stop(prev))
    return carry, float(ENDINGS.get(token, 0.0))

programs.sol:
"""A sparse lexical predictor, not a model of every small fluctuation.

It distinguishes C-like declarations and English possessives at document
beginnings. In Chinese, it recognizes 其 and a few resultative expressions:
removal (去/掉), completion (光), cleaning, and strengthening, as well as
selected/high-quality descriptions.
Chinese quantity expressions receive negative values. Other text gets a
small background value. Only the preceding character is remembered.
"""

READS = ()

DECLARATIONS = {
    'int', 'long', 'short', 'float', 'double', 'char', 'bool', 'boolean',
    'void', 'string', 'String', 'static', 'const', 'unsigned', 'var', 'let',
    'private',
}
POSSESSIVES = {'my', 'your', 'his', 'her', 'its', 'our', 'their', 'own'}
FUNCTION_WORDS = {
    'a', 'an', 'the', 'of', 'in', 'on', 'at', 'to', 'for', 'from', 'with',
    'by', 'and', 'or', 'but', 'as', 'if', 'when', 'is', 'are', 'was', 'be',
    'this', 'that', 'these', 'those', 'we', 'you', 'it', 'he', 'she', 'they',
}
REMOVAL = set('免脱脫辞辭减減消除褪失拭擦删刪撤切淡散抹割滤濾刮占片削少')


def beginning(s):
    word = s.strip()
    if s.startswith('<|'):
        return 0.17
    if not word:
        return -0.03
    if word in {'const', 'unsigned'}:
        return 0.5
    if word in DECLARATIONS:
        strong = word in {'int', 'char', 'void', 'long', 'static', 'private'}
        value = 2.2 if strong else 1.4
        return value - (1.2 if s[0].isspace() else 0.0)
    if word.lower() in POSSESSIVES:
        return 0.35
    if s in {'/*', '/**'}:
        return 1.55
    if word.startswith(('//', '#include', '#!')):
        return 0.5
    if s in {'‘', '’'}:
        return 1.25
    if len(word) == 1 and word.isascii() and word.isdecimal():
        return 0.3 if int(word) >= 5 else 0.0
    if word.isascii() and word.isalpha():
        if word.lower() in {'of', 'in', 'with', 'for', 'and', 'but', 'when'}:
            return -0.5
        if len(word) == 1:
            return -0.32
        if word.lower() in FUNCTION_WORDS:
            return -0.2
        return -0.2 if s[0].isupper() else -0.06
    if word[0].isalpha():
        return -0.15
    return 0.02


def step(carry, prefix, upstream):
