        value = 1.5
    elif word in {'强', '強'} and last == '增':
        value = 1.3
    elif word in {'提升', '提高'}:
        value = 0.2
    elif word in {'优质', '優質', '精选', '精選'}:
        value = 0.75
    elif word in {'去', '去了'}:
        value = 2.2 if last in REMOVAL else -0.05
    elif word == '掉':
        value = 1.6 if last in {'脱', '脫', '撕'} else 0.18
    elif word == '光':
        value = 1.3 if last in '脱脫散增遮败敗粉' else -0.05
    elif word == '震' and last in {'减', '減'}:
        value = 1.5
    elif word in {'净', '淨', '面'} and last in {'洗', '洁', '潔'}:
        value = 1.3
    elif word in {'任何', '很多', '最少', '最多', '很少'}:
        value = -0.5
    elif word in {'许多', '許多', '至少', '不少', '无数', '無數', '太多'}:
