"""Approximate a code type/value-introduction response, strongest on `new`.

Constructor `new` gets a large response after assignment, return, or throw,
not when it is the English adjective or a Rust method name. Smaller rules
recognize declarations, type tests/casts, Go address and slice construction,
and SQL table introductions. Primitive types immediately after `new` get a
negative response. This is a syntax heuristic, not a complete language parser.
A rolling 200-character suffix supplies context and resets between documents.
"""
import re

READS = ()
CODE = re.compile(r'[;{}]|\w[.\[]\w|\w\(|\n[ \t]+\S|:=|=>')
PYTHON_CALL = re.compile(r'\b(?:print|def)\s*\([^;{}]*$', re.S)
NON_CONSTRUCTOR = re.compile(r'\b(?:def|fn|func)\b|:=|\b(?:fmt|cout)\b')
VISIBILITY = {'public', 'private', 'protected'}
DECLARATIONS = {
    'const', 'static', 'final', 'class', 'struct', 'interface',
    'enum', 'func', 'impl', 'pub', 'async',
}
PRIMITIVE_TYPES = {
    'int', 'byte', 'char', 'short', 'long', 'float',
    'double', 'boolean', 'bool',
}


def predict(token, before):
    word = token.strip()
    code = bool(CODE.search(before[-160:]))

    # Opening punctuation can share a token with the keyword.
    if word == 'new' or token in ('(new', '=new', '[new'):
        lead = token[:-3].strip()
        end = (before + lead).rstrip()
        if end.endswith(('::', '.')):
            return -0.25
        if PYTHON_CALL.search(end[-100:]):
            return -0.15
        if end.endswith('='):
            if NON_CONSTRUCTOR.search(before[-160:]):
                return 6.4
            return 9.8 if lead else 11.1
        if re.search(r'\bthrow$', end):
            return 11.3
        if re.search(r'\breturn$', end):
            return 9.9
        if end.endswith(('||', '??', '=>')):
            return 10.0
        if end.endswith(('(', ',')):
            return 7.3 if code or lead == '(' else -0.2
        if end.endswith((':', '{')):
            return 5.6 if code else -0.2
        if end.endswith('['):
            return 2.0
        return 4.0 if not end else -0.2
    if token == '.New':
        return 5.1

    # Places where a type or an allocated object's name is expected.
    if word in PRIMITIVE_TYPES and re.search(r'\bnew\s*$', before):
        return -3.3
    if token == ',' and re.search(
        r'\b(?:isinstance|issubclass)\([^,()]*$', before
    ):
        return 3.3
    if token == '<' and re.search(r'\b[A-Z][A-Za-z0-9_]*$', before):
        return 1.2
    if word == 'instanceof':
        return 6.6
    if token.endswith('sizeof'):
        return 3.6
    if word == 'typeof':
        return 1.1
    if word == 'as' and code:
        return 1.5 if re.search(r'(?:[)\]]|\w+\.\w+)\s*$', before) else 0.1

    go = bool(re.search(r':=|\bfunc\b', before[-160:]))
    if word == '&':
        if go and re.search(r'(?:[,=(]|\breturn)\s*$', before):
            return 4.8
        if re.search(r'(?:=|\breturn)\s*$', before):
            return 2.3
        return 0.4 if code else 0.0
    if word == '(&':
        return 4.8 if go else 1.3
    if word == '([]':
        return 5.5 if before.rstrip().endswith('make') else 1.3
    if word == '[]':
        return 0.5
    if word == '(!':
        return 1.0

    # Declaration and assignment cues have a weaker response.
    if word in VISIBILITY:
        return 2.2 if '\t' in token else (2.0 if code else -0.1)
    if word in DECLARATIONS:
        return 0.6 if code else 0.0
    if word in {'except', 'catch', 'raise'}:
        return 1.0 if code else 0.0
    if word == '(function' or (word == 'function' and re.search(
        r'(?:=|\breturn)\s*$', before
    )):
        return 1.4
    if token == ' =':
        if re.search(r'(?:\b(?:const|let|var)\s+|\bself\.|\bthis\.|\$)\w+$', before):
            return 0.9
        return 0.45 if code else 0.08
    if word == ':=':
        return 0.95
    if word == 'nil':
        return 1.0
    if word in {'==', '===', '!=', '!=='}:
        return 0.3

    if word.lower() in {'from', 'join', 'into'}:
        if re.search(r'\b(?:select|delete)\b[^;]*\*\s*$', before, re.I):
            return 4.0
        if word.lower() == 'join' and re.search(
            r'\b(?:inner|outer|left|right|cross)\s*$', before, re.I
        ):
            return 4.0
        if word.lower() == 'into' and re.search(r'\binsert\s*$', before, re.I):
            return 4.0
        if word.isupper() and re.search(
            r'\b(?:SELECT|DELETE|INSERT|UPDATE)\b', before[-160:], re.I
        ):
            return 2.4
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    value = predict(token, before)
    return (document, (before + token)[-200:]), value

