"""layers.1.mlp.down_proj:3117 -- a mostly silent direction with a few readable effects.

Its activation is small noise (std ~0.03) almost everywhere. It is clearly negative in two
places: at the first token of a row (a document start), and on the token right after
<|endoftext|> (the start of a new document inside a row). It is also weakly negative on
web/URL/handle-like tokens (.com, www, @, github, ://), and on non-ASCII punctuation, and
weakly positive on kana, hangul, Thai, Devanagari and partial UTF-8 bytes. Everything else
is predicted as 0.
"""
import unicodedata

READS = ()

ROW_START = -0.055
AFTER_EOT = -0.06
WEB_PARTS = (".com", "www", "://", "@", "github", ".io", ".org", ".net", "http")
POS_SCRIPTS = ("KATAKANA", "HIRAGANA", "HANGUL", "THAI", "DEVANAGARI")


def _is_nonascii_punct(s):
    return len(s) > 0 and ord(s[0]) > 127 and all(unicodedata.category(c).startswith("P") for c in s)


def _is_positive_script(s):
    return len(s) > 0 and any(
        any(name in unicodedata.name(c, "") for name in POS_SCRIPTS) for c in s
    )


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if prefix.position == 0:
        return carry, ROW_START
    if prev == "<|endoftext|>":
        return carry, AFTER_EOT
    if any(part in tok for part in WEB_PARTS):
        return carry, -0.03
    if _is_nonascii_punct(tok):
        return carry, -0.014
    if "�" in tok or _is_positive_script(tok):
        return carry, 0.008
    return carry, 0.0

"""Layer-1 MLP down-projection component 3118: a document-opening feature.

The component is nearly silent inside a document (typical size 0.04) and speaks mainly at
a document's first token. That token has no earlier text to attend to, so its activation
depends only on the word, symbol or byte that opens the document. This program predicts it
by word class:
  * a NUL byte ("\\x00") opening a document gives the largest value, about 31 (the
    component's maximum; it is the one token that is that large);
  * a line or tab break opens a document: strongly positive;
  * verbs of giving, having and providing ("Give", "contains", "provides", "allows", "with")
    are the most positive words; other verbs are mildly positive;
  * function words that continue a sentence (" of", " a", " is", " that", " can") are positive;
  * capitalised sentence openers ("The", "This", "I", "How") and business or people nouns
    ("investors", "entrepreneurs") are negative;
  * single letters, digits, non-English script, quotes and indentation are mildly negative.
Every other position predicts 0. Only the document's first token is looked at, so the
program has no carry: a position opens a document when its document id changes.
"""

import re

READS = ()


def _forms(base):
    """A base verb with its regular inflections."""
    out = {base, base + "s", base + "es", base + "ed", base + "d", base + "ing"}
    if base.endswith("e"):
        out.add(base[:-1] + "ing")
    if base.endswith("y"):
        out |= {base[:-1] + "ies", base[:-1] + "ied"}
    return out


GIVE_VERBS = set()
for _w in "have give contain include provide offer create produce generate receive allow enable deliver add need require ensure make".split():
    GIVE_VERBS |= _forms(_w)
GIVE_VERBS |= {"has", "gave", "given", "made", "provided", "contained", "included", "with", "without"}

OTHER_VERBS = set()
for _w in (
    "get show find use assign classify compare perform demonstrate depict represent simulate expose "
    "notify initialize store save load fetch retrieve update delete prevent avoid hold own possess "
    "comprise obtain acquire earn donate purchase recommend praise assure verify decorate illustrate "
    "examine explore measure estimate invoke manage operate control process filter sort apply check "
    "count display print open close cover feature supply equip accept reflect reveal indicate identify "
    "replace remove insert append select choose permit forbid cause lead extend connect link combine "
    "transform modify adjust correct fix solve analyze evaluate enhance boost maintain protect "
    "calculate compute return set write read run call define implement handle support describe "
    "explain convert improve reduce increase achieve build send bring keep let put see look want try help"
).split():
    OTHER_VERBS |= _forms(_w)

CONTINUERS = set("a an of is are was be can could should would will may must that for with from have has".split())

CAPITAL_OPENERS = set("the this i how what when where who why you your they he she we it a an in".split())

BUSINESS_PEOPLE = set(
    """entrepreneur entrepreneurs investor investors business businesses professional professionals
    leader leaders expert experts founder founders teacher teachers student students growth success
    health team skills strength strengths insight insights trend trends talent talents engineer engineers
    specialist specialists trader traders lender lenders enthusiasm urgency productivity patience
    loyalty grief arrogance intuition responsiveness professionalism""".split()
)


def _value(text):
    """Predicted activation for a document's first token, given its decoded text."""
    word = text.strip().lower()
    if "\n" in text or "\r" in text:
        return 2.7
    if "\t" in text or "\xa0" in text:
        return 3.5
    if text.strip() == "":
        return 0.6 if text == " " else -0.7
    if text == "\x00":
        return 31.07
    if text == "<|endoftext|>":
        return 8.0
    if re.fullmatch(r"<\|.*\|>", text):
        return -0.4
    if re.fullmatch(r"\s*\d+", text):
        return -0.75
    if not text.isascii():
        return -0.6
    if not any(c.isalnum() for c in text):
        return -0.8 if ('"' in text or "'" in text) else -0.4
    if len(word) == 1:
        return -0.5 if text.startswith(" ") else -1.2
    if word in GIVE_VERBS:
        return 3.5
    if word in OTHER_VERBS:
        return 1.3
    if word in CONTINUERS and text.startswith(" "):
        return 2.0
    if text.strip()[:1].isupper() and word in CAPITAL_OPENERS:
        return -1.5
    if word in BUSINESS_PEOPLE:
        return -2.4
    if re.fullmatch(r"[a-z]+", word):
        return -0.6 if text.startswith(" ") else 0.2
    return 0.0


def step(carry, prefix, upstream):
    t = prefix.position
    starts_document = t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]
    if not starts_document:
        return None, 0.0
    return None, float(_value(prefix.token_strings[t]))

programs.sol:
"""Sparse contextual and formatting responses of this component.

Predict a strong negative value for the old-line minus in ``@@ -`` and a
smaller one for ``App`` in ``Vet. App.`` citations. Include weaker diff and
chat markers. At row/document starts (also after an end-of-text marker),
use whitespace, case and character type for a small baseline adjustment.
Other tokens get zero: most token-specific variation remains unexplained.
"""
READS = ()

CHAT_BOUNDARIES = {
    '<|im_start|>': -0.11,
    '<|im_end|>': -0.02,
    '<|endoftext|>': -0.02,
    '<tool_call>': -0.08,
    '</tool_call>': 0.09,
    '<tool_response>': 0.15,
    '<think>': -0.12,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    tail = '' if start else carry[1]
    token = prefix.token_strings[-1]
    value = CHAT_BOUNDARIES.get(token, 0.0)
    if token == ' -' and tail.endswith('@@'):
        value = -0.95
    elif token == '@@':
        value = -0.15
    elif token == ' b' and tail.endswith('+++'):
        value = -0.32
    elif token == '+++':
        value = -0.16
    elif token == '---':
        value = -0.11
    elif token == ' App' and tail.endswith('Vet.'):
        value = -0.43
    elif (
        (start or tail.endswith('<|endoftext|>'))
        and token not in CHAT_BOUNDARIES
    ):
        word = token.strip()
        spaced = token[:1].isspace()
        if not word:
            value = -0.05
        elif not word.isascii():
            value = -0.06
        elif word.isdecimal():
            value = -0.025
        elif word.isalpha():
            if word.islower():
                value = -0.075 if spaced else -0.27
            elif word.isupper():
                value = 0.08 if spaced else 0.05
            elif word.istitle():
                value = -0.035 if spaced else -0.16
            else:
                value = -0.15
        elif not any(c.isalnum() for c in word):
            value = 0.12 if spaced else -0.015
        else:
            value = -0.15 if not spaced else -0.05
    tail = (tail + token)[-80:]
    return (doc, tail), value

"""Approximate the component's clearest spelling-sensitive responses.

Isolated Japanese vowel kana, short vowel-starting endings and quotation
fragments get positive values. Their strength depends on the preceding vowel
sound, especially a repeated written i. Greek epsilon has related rules.
A Latin ii chunk following i and Cyrillic э following o/u get negative values.
Middle-dot runs and document-start categories have separate small rules.
Other cases return zero: this deliberately leaves irregular vocabulary and
split-character effects unexplained rather than memorizing token identities.
"""
import unicodedata as ud

READS = ()

HIRAGANA_VOWELS = dict(zip('あいうえお', (0.2, 1.4, 1.9, 0.5, 0.25)))
KATAKANA_VOWELS = dict(zip('アイウエオ', (0.0, 0.6, 0.25, 0.0, 0.0)))
QUOTATION_FRAGMENTS = {'とい', 'という', 'っていう'}


def unaccented(s):
    return ''.join(c for c in ud.normalize('NFD', s) if not ud.combining(c))


def ending_vowel(text):
    """Vowel of the last letter or kana syllable; unknown for Han characters."""
    if not text:
        return ''
    c = unaccented(text[-1]).lower()
    if len(c) != 1:
        return ''
    if c in 'aeiou':
        return c
    if c in 'αεηιουω':
        return dict(zip('αεηιουω', 'aeiiouo'))[c]
    if c in 'аеиоуыэюя':
        return dict(zip('аеиоуыэюя', 'aeiouieua'))[c]
    name = ud.name(c, '')
    if name.startswith(('HIRAGANA LETTER', 'KATAKANA LETTER')):
        if name[-1] in 'AIUEO':
            return name[-1].lower()
    return ''


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    start = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    prev = '' if start else prefix.token_strings[-2]
    vowel = ending_vowel(prev)
    value = 0.0

    if s in HIRAGANA_VOWELS:
        value = HIRAGANA_VOWELS[s]
        if s == 'い':
            value += {'i': 1.8, 'u': 0.6, 'o': 0.2}.get(vowel, 0.0)
        elif s == 'う':
            value += {'i': 0.5, 'u': -0.3, 'o': -0.2}.get(vowel, 0.0)
        elif s == 'え' and vowel == 'i':
            value += 0.3
    elif s in KATAKANA_VOWELS:
        value = KATAKANA_VOWELS[s]
        if s == 'イ':
            value += {'i': 0.6, 'u': 0.6, 'e': -0.25}.get(vowel, 0.0)
    elif s == 'ー':
        value = 0.45
    elif s in QUOTATION_FRAGMENTS:
        value = 0.85
    elif len(s) > 1 and all(c in HIRAGANA_VOWELS for c in s):
        value = 1.1
    elif 1 < len(s) <= 3 and s[0] in 'えい':
        if all('HIRAGANA' in ud.name(c, '') for c in s):
            value = 0.5 if s[0] == 'え' else 0.15
            if s[0] == 'え' and vowel == 'i':
                value += 0.4

    if s in ('い', 'イ') and prev.endswith(('い', 'イ')):
        value += 1.8
    if s in ('ε', 'έ'):
        value = 0.65 if s == 'έ' else 0.0
        value += {'i': 1.8, 'u': 2.0, 'a': 2.0}.get(vowel, 0.0)
    if s.lower() == 'ii' and prev.lower().endswith('i'):
        value = -3.7
    if s.startswith('э') and vowel in ('o', 'u'):
        value = -0.8
    if len(s) >= 2 and set(s) == {'·'}:
        value = 0.6

    if start:
        if s == '//\n':
            value -= 3.6
        elif s and s[0].isupper() and s.isascii():
            value -= 0.24
        elif s.isdigit():
            value -= 0.37
        elif s.startswith(' ') and s.strip().isalpha():
            value -= 0.1
    return None, float(value)

programs.haiku:
"""Candidate 5: vowel-sound kana and Greek e-vowels, with a document-start effect.

Positive. The letters that carry a Japanese syllable's vowel sound at the end of a stem:
う (about +1.8) and い (about +1.5), the weaker kana え, お, あ, and the katakana long-vowel
mark ー with イ, ウ, エ (about +0.4). A longer all-kana token that ends in such a vowel
(いう, という, える) is weaker (about +0.25). Also the Greek e-vowels έ, Ε, ε (about +0.25).

Document start. The first token of each document (positions restart there, so it sees
only itself) is negative: about -0.37 for a digit, -0.23 for a capitalised word, and -0.07
for anything else.

Everything else is about zero: the activation is mostly small, unpredictable noise around 0.
"""

READS = ()

VOWEL_I = {"い": 1.5}
VOWEL_U = {"う": 1.8}
WEAK_VOWEL_KANA = {"え", "お", "あ", "ー", "イ", "ウ", "エ"}
GREEK_E = {"έ", "Ε", "ε"}
VOWEL_ENDINGS = set("いうえおあー")


def at_document_start(prefix):
    ids = prefix.document_ids
    return len(ids) == 1 or ids[-1] != ids[-2]


def is_kana(c):
    return "぀" <= c <= "ヿ"


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if at_document_start(prefix):
        if s.strip().isdigit():
            return None, -0.37
        if s[:1].isupper():
            return None, -0.23
        return None, -0.07
    if s in VOWEL_I:
        return None, VOWEL_I[s]
    if s in VOWEL_U:
        return None, VOWEL_U[s]
    if s in WEAK_VOWEL_KANA:
        return None, 0.4
    if s in GREEK_E:
        return None, 0.25
    if len(s) > 1 and s[-1] in VOWEL_ENDINGS and all(is_kana(c) for c in s):
        return None, 0.25
    return None, 0.0

programs.sol:
"""A partial approximation of a document-start/header response.

An initial `Title:` label produces a strong positive pulse on its colon.
Otherwise, values are usually near zero after the initial token (or its
uninterrupted repetitions). Initial values use grammatical classes,
indentation, message markers, and English verb membership. Paired middle-dot
filler has a negative value. Token-specific variation remains unexplained.
"""
import inflect
import wordnet

READS = ()

# Grammatical classes used only at the start of a document.
FIRST_PERSON = {'i', 'me', 'my', 'mine', 'we', 'us', 'our', 'ours'}
PLURAL_DEICTIC = {'they', 'them', 'their', 'theirs', 'these', 'those'}
SINGULAR_DEICTIC = {'the', 'this', 'that'}
OTHER_PERSONAL = {
    'he', 'him', 'his', 'she', 'her', 'hers', 'it', 'its',
    'you', 'your', 'yours',
}
WORDS = inflect.engine()
COUNT_WORDS = {WORDS.number_to_words(n) for n in range(2, 11)}
ORDINALS = {WORDS.number_to_words(WORDS.ordinal(n)) for n in range(1, 6)}
DIRECTION = {'up', 'down', 'out', 'over', 'into', 'onto', 'upon'}
AUXILIARIES = {'are', 'be', 'being', 'have', 'has', 'had'}
MODALS = {'can', 'could', 'would', 'should', 'may', 'might', 'must'}


def initial_value(text):
    word = text.strip().lower()
    if text == '··':
        return -8.25
    if text == '<|im_start|>':
        return 1.194
    if text == '<|endoftext|>':
        return 4.075
    if word in FIRST_PERSON:
        return -2.9
    if word in PLURAL_DEICTIC:
        return 6.0
    if word in SINGULAR_DEICTIC:
        return -0.6
    if word in OTHER_PERSONAL:
        return 0.7
    if word in COUNT_WORDS:
        return 5.6
    if word in ORDINALS:
        return -4.2
    if word in DIRECTION:
        return 4.0
    if word in AUXILIARIES:
        return 1.8
    if word in MODALS:
        return -1.0
    if word in {'to', 'of'}:
        return 2.5
    if word in {'in', 'as'}:
        return -2.0
    if word in {'or', 'but'}:
        return 2.5
    if word == 'an':
        return -5.0
    if word in {'is', 'was', 'were', 'been'}:
        return 0.4
    if word == 'one':
        return -1.2
    if text.isspace():
        if '\t' in text or len(text) >= 3 and '\n' not in text:
            return -3.2
        return -0.3
    if word.isalpha() and len(word) >= 3:
        if word.isascii() and 'verb' in wordnet.parts_of_speech(word):
            return 1.9
        return 0.7
    return 0.0


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        first, pos, repeated = text, 0, True
    else:
        _, first, pos, repeated = carry
        pos += 1
    repeated = repeated and text == first
    value = 0.0
    if repeated:
        value = initial_value(text)
    elif pos == 1 and first == 'Title' and text == ':':
        value = 35.54
    return (doc, first, pos, repeated), value

"""Opening-token bias plus sparse code and metadata boundaries.

At a document's opening (including an initial run of the same token), word
length, English frequency, case, digit value and character type give a baseline.
Elsewhere the baseline is nearly zero. Larger pulses recognize issue-record
markers, declarations, documentation openings and repository filenames/URLs,
plus a few posting-header, license and misconduct-report phrases. These rules
capture some activation variation; most output-distribution error remains.
"""
import math
import re
import regex
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=8192)
def opening_value(s):
    """A coarse spelling-based estimate when no preceding content is present."""
    w = s.strip()
    if w.isascii() and w.isalpha():
        f = zipf_frequency(w.lower(), 'en')
        v = -0.043 - 0.056 * min(len(w), 12) - 0.059*f + 0.011*f*f
        v -= 0.072 * s[:1].isspace()
        v -= 0.066 * w[:1].isupper() + 0.020 * w.islower()
        return v + 0.316 * w.isupper()
    if len(w) == 1 and w in '0123456789':
        return -0.55 + 1.10 * math.exp(-0.55 * int(w))
    if not w:
        return -0.5 if '\n' in s or '\t' in s else -0.1
    if s == r'\t':
        return -2.72
    if s == r'\n':
        return -1.71
    if s == r'\[':
        return 1.51
    if s.startswith('\\'):
        return -1.15
    if s == '<|endoftext|>':
        return -2.02
    if w in ('"""', "'''"):
        return -3.6 if '\n' in s else -2.1
    if regex.fullmatch(r'\p{Quotation_Mark}', w):
        return -1.0
    return -0.16 if s.isascii() else -0.25


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        tail, previous, opening, age = '', '', True, 0
    else:
        _, tail, previous, opening, age = carry
        opening = opening and s == previous
    value = opening_value(s) if opening else 0.002
    word = s.strip()
    line = tail.rsplit('\n', 1)[-1]
    modifiers = line.split()
    first_comment = '#!' in tail and not tail.split('\n', 1)[-1].strip()

    if s == '··' and (opening or previous == s):
        value = -2.54
    elif tail.endswith('<issue_comment') and s == '>Title':
        value = -8.0
    elif tail.endswith('<issue') and s in ('_start', '_closed', '_comment'):
        value = {'_start': -3.4, '_closed': -2.1, '_comment': -0.8}[s]
    elif s == 'issue' and tail.endswith('<'):
        value = -1.2 if age < 3 else 0.2
    elif s == '_' and previous == 'username':
        value = -0.7
    elif s == 'attributes' and tail.endswith('.git'):
        value = 1.9
    elif word == 'class' and modifiers and set(modifiers) <= {
        'public', 'abstract', 'partial', 'static', 'final', 'private', 'protected'
    }:
        value = -0.3 if 'static' in modifiers else -1.1
    elif word == 'class' and not line.strip() and '<?php' in tail:
        value = -0.45 if 'namespace' in tail else -0.9
    elif word == 'namespace' and not line.strip() and (
        '<?php' in tail or 'using ' in tail
    ):
        value = -1.8 if '<?php' in tail else -1.0
    elif word == 'declare' and not line.strip() and '<?php' in tail:
        value = -1.75
    elif s == ':\n':
        if line.strip().lower() == 'answer':
            value = -1.5 if 'translate' in tail.lower() else -0.6
        elif line.strip() in ('public', 'private', 'protected'):
            value = -0.3
        elif line.strip() == 'Question' and age < 3:
            value = -3.4
    elif word in ('"""', "'''") and '\n' in s and not opening:
        if first_comment:
            value = -3.2
        elif re.search(r'\bdef\b[^\n]*:\s*$', tail):
            value = -0.75 if 'import ' in tail else -0.35
    elif s.startswith('/**') and '<?php' in tail:
        value = -1.0
    elif s.startswith('#') and not s.rstrip('\r\n').strip('#') and first_comment:
        value = -1.3
    elif s in ('repo', 'errors') and previous == '://':
        value = -0.8 if s == 'repo' else -1.15
    elif s in ('/repos', '/assets') and '://' in tail:
        value = -1.0 if s == '/repos' else -0.8
    elif word == 'on' and previous.strip() == 'Posted':
        value = 1.15
    elif word == 'reply' and previous.strip() == 'Latest':
        value = -1.05
    elif word == 'details' and previous.strip().lower() == 'more':
        value = 0.45
    elif s == '**\n' and line.startswith('**') and line.endswith(':'):
        value = -0.7
    # The damages clause of a permissive software license.
    elif word == 'EXEMPLARY' and 'SPECIAL,' in tail:
        value = -1.7
    # 'Accept/receive' in reports about taking gifts or bribes.
    elif s == '收受' and any(w in tail for w in ('纪律', '财物', '礼品', '任用')):
        value = -0.8

    return (doc, (tail + s)[-256:], s, opening, age + 1), float(value)

programs.haiku:
"""Scratch: dot-leader + document start + a few code/URL tail tokens."""
READS = ()

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if prefix.position > 0 else ""
    if prefix.position == 0:
        return carry, -0.25
    if tok == "··":
        return carry, -2.54
    if tok == "attributes" and prev == ".git":
        return carry, 2.2
    if tok == " class" and prev in ("public", " public"):
        return carry, -0.8
    if tok == "namespace" and prev.endswith("\n\n"):
        return carry, -0.9
    if tok in ("repo", "/repos") and prev == "://":
        return carry, -0.9
    return carry, 0.0

programs.sol:
"""Approximate a response to suffix-sized word continuations.

Possessive -'s is distinguished from pronoun contractions. Capitalized
and person-denoting stems get stronger responses. Related rules cover -son/-sen,
-man/-men, -ton/-town, short in-word s/z pieces, and repeated middle dots.
Capitalization, stem length, and dictionary information modulate strength;
this is a local spelling approximation, not a full grammatical analysis.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency
import wordnet

READS = ()
CONTRACTIONS = {
    'it', 'that', 'what', 'he', 'she', 'there', 'here', 'who',
    'how', 'where', 'let', 'this',
}
INDEFINITE = {
    'someone', 'anyone', 'everyone', 'noone', 'somebody', 'anybody',
    'everybody', 'nobody', 'something', 'anything', 'everything', 'nothing',
}

# Each tuple is an intercept followed by the strengths of the named
# properties passed to affine() below.
PARAMETERS = {'contraction': (-0.0225,),
 'encoded_possessive': (0.9024,),
 'linking_s': (-0.1998, 0.0783, 0.4111, 0.1264, 0.1583, 0.2111),
 'middle_dots': (1.1409,),
 'patronymic': (0.6135, 0.743, 1.0734, 0.2407, 0.2045, 1.1294),
 'person_compound': (0.0514, 0.1995, 0.2551, 0.2484),
 'place_compound': (0.3533, 0.588, 0.4219),
 'possessive': (0.0401, 0.5866, 0.2918, 0.2953, 0.3106, -0.0987)}


def affine(kind, *properties):
    weights = PARAMETERS[kind]
    return weights[0] + sum(w*x for w, x in zip(weights[1:], properties))


@lru_cache(maxsize=10000)
def person(word):
    return wordnet.is_a(word.lower(), 'person')


@lru_cache(maxsize=30000)
def familiar(word):
    return max(zipf_frequency(word, lang) for lang in ('en', 'de', 'nl'))


def predict(stem, token, previous):
    s = token.lower()
    capital = stem[:1].isupper()
    size = min(len(stem), 10) / 10
    if s in ("'s", '’s') or (s == 's' and previous.endswith(("'", '’'))):
        if stem.lower() in CONTRACTIONS:
            return PARAMETERS['contraction'][0]
        return affine('possessive', capital, size, person(stem),
                      stem.lower().endswith(('er', 'or', 'ist')),
                      stem.lower() in INDEFINITE)
    if s == ';s':  # The end of an HTML-encoded apostrophe followed by s.
        return PARAMETERS['encoded_possessive'][0]
    if token and set(token) == {'·'} and len(token) > 1:
        return PARAMETERS['middle_dots'][0]
    if not stem:
        return 0.
    if (s in ('son', 'sons', 'sen', 'сон', 'сона')
            or s in ('on', 'ons') and capital and stem.lower().endswith('s')):
        frequency = familiar(stem)
        drop = min(0., familiar(stem + token) - frequency)
        return affine('patronymic', capital, size, frequency - 4,
                      drop, person(stem))
    if s in ('man', 'men'):
        return affine('person_compound', capital, size, person(stem))
    if s in ('ton', 'town'):
        return affine('place_compound', capital, size)
    if len(s) <= 4 and s.startswith(('s', 'z')) and s.isalpha():
        cluster = len(s) > 1 and s[1] not in 'aeiouy'
        return affine('linking_s', capital, size, s == 's', cluster,
                      person(stem))
    return 0.


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    stem, previous = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    value = predict(stem, token, previous)
    # Preserve a stem across a separately tokenized (possibly escaped) quote.
    if token not in ("'", '’', "\\'"):
        ending = re.search(r'[^\W\d_]+$', token)
        stem = (((stem if ending.start() == 0 else '') + ending.group())[-80:]
                if ending else '')
    return (doc, stem, token), float(value)

"""Approximate a feature for physical parts, poles, and ends of things.

Spelling identifies a few related noun families; modifiers distinguish spatial
'ends' and tangible 'strings' from temporal ends and programming strings.
A small dictionary check also recognizes compound noun heads across tokens.
Han rod/handle characters are included. Recognized parts leave a smaller
negative continuation on following 'of'. An isolated source-comment opener
at document start is positive. These are lexical cues, not a full
interpretation of the sentence.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
RODS = set('rod pole stick stem stalk'.split())
PARTS = set(('pin peg shaft pipe wire rail rope hook hinge cord spring '
             'spout pod pad').split())
HEADS = RODS | PARTS | {'pot', 'bed', 'string', 'pick', 'shelf'}
SPATIAL = set(('one each both either other opposite upper lower bottom top '
               'left right tail foot head working fixed').split())
END_MODIFIERS = set(('front rear back leading trailing distal proximal free '
                     'closed open tight receiving threaded north south east west '
                     'inner outer near far high low dead').split())
MATERIALS = set('wood wooden metal steel iron copper brass plastic rubber glass'.split())
SHAPES = set('flat round square long thin short straight vertical horizontal'.split())
NOMINAL = set('a an the this that these those my your its first second next'.split())
ENGLISH = NOMINAL | set(
    'of and with from for on by is are was has it they you'.split()
)
BED_PREFIXES = set('test river road stream sea foot flower flat water'.split())
CRAFT = re.compile(
    r'\b(tie|knot|bead|thread|yarn|tubing|guitar|violin|cotton|nylon|kite|'
    r'shawl|plank|tension|pendulum|classical|wool|magnet|knit|crochet|pull|'
    r'physics)(?:s|ing)?\b'
)


@lru_cache(maxsize=8192)
def noun_head(word):
    for head in sorted(HEADS, key=len, reverse=True):
        if word == head:
            return head, False
        if word.endswith(head):
            modifier = word[:-len(head)]
            if (len(modifier) >= 3 and wordnet.parts_of_speech(modifier)
                    and wordnet.is_a(word, 'physical_entity')):
                return head, True
    return '', False


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, fragment, recent, last_value = '', '', '', 0.0
    else:
        _, previous, fragment, recent, last_value = carry
    text = prefix.token_strings[-1]
    word = text.strip().lower()
    prev = fragment.lower() or previous.strip().lower()
    spaced = bool(text[:1].isspace())
    base = word[:-1] if word.endswith('s') else word
    joined = word if spaced else fragment.lower() + word
    joined_base = joined[:-1] if joined.endswith('s') else joined
    compound = False
    if not spaced:
        head, is_compound = noun_head(joined_base)
        if head and len(base) <= len(head):
            base = head
            compound = is_compound and not text[:1].isupper()
        elif fragment and base == 'rod':
            base = ''
    value = 0.0

    if base == 'end' or word == '-end':
        value = -0.8 if word.endswith('s') else -0.4
        if not spaced:
            value = -1.2 if word == '-end' else -0.08
        elif prev in SPATIAL:
            value = -4.3
        elif prev in END_MODIFIERS:
            value = -3.0
        elif prev in {'inlet', 'outlet', 'root', 'cut', 'split', 'opposed'}:
            value = -2.0
    elif base == 'bed':
        value = -0.2
        if not spaced and prev in BED_PREFIXES:
            value = -1.7 if previous == '/test' else -2.1
        elif not spaced and fragment:
            value = 0.0
    elif base == 'pot' or (word == 'ots' and prev.endswith('p')):
        if not spaced and (
            prev.endswith(('crock', 'crack', 'jack')) or word == 'ots'
        ):
            value = -3.4
        elif prev in MATERIALS | {'hot', 'instant', 'flower', 'pouring'}:
            value = -3.0
        elif sum(w in ENGLISH for w in
                 re.findall(r'[a-z]+', recent.lower())[-10:]) >= 2:
            value = -2.3
        elif not spaced:
            value = -1.0
    elif base == 'string':
        value = 0.12
        if CRAFT.search(recent.lower()):
            value = -2.5
        if not spaced and prev.endswith(('draw', 'drill')):
            value = -5.2
        elif previous == '/doc':
            value = -1.9
    elif base in RODS:
        value = -2.0 if base == 'rod' else -1.2
        if base == 'pole':
            value = -3.2 if text.strip()[:1].isupper() else -2.5
            if prev in {'flag', 'telephone', 'utility', 'ski'}:
                value = -5.5
        if prev in {'fishing', 'piston', 'connecting', 'glue', 'upright', 'cross'}:
            value -= 1.5
        if prev in {'el', 'la', 'av', 'to'}:
            value = 0.0
    elif base in PARTS:
        value = -0.7
        if prev in MATERIALS | SHAPES:
            value = -1.5
    elif base in {'handle', 'stand', 'bar'}:
        value = -0.1
        if prev in MATERIALS | SHAPES:
            value = -1.5
        elif base == 'handle':
            value = -1.6 if prev in NOMINAL else 0.15

    if compound and base not in {'bed', 'string'}:
        value = min(value, -2.7)
    if word == 'of' and last_value < 0:
        value = 0.2 * last_value
    # Rods and handles in Han text, including split UTF-8 characters.
    raw = prefix.token_bytes[-2:] if previous else prefix.token_bytes[-1:]
    han = b''.join(raw).decode('utf-8', 'ignore')
    if han.endswith(('竿', '杆', '桿', '柄', '柱')):
        value = -2.5
    if text == '//\n' and (carry is None or previous == '<|endoftext|>'):
        value = 3.65

    match = re.search(r'[A-Za-z]+$', fragment + text)
    fragment = match.group()[-24:] if match else ''
    return (doc, text, fragment, (recent + text)[-100:], value), value

programs.haiku:
"""Long, thin physical objects, and the ends of them.

The component goes negative on words for long, thin physical objects used as nouns in
prose: pole, rod, stick, pin, peg, shaft, stem, pipe, wire, strap, and also pot, pad,
shelf, pier, chair, hole, spring. It goes most negative on "end"/"ends" when it names one
end of such an object ("the opposite end", "one end", "upper end"); a bare "the end" is
only mildly negative. It is strongly negative on "bed" (as in "test/bed") in any use.
The same object words in code (identifiers, after punctuation) are much weaker. A middle
dot "··" gives a constant positive value. Everything else is about zero.
"""

READS = ()

# Typical activation on the word when it is a physical noun in prose.
OBJECT = {
    "pole": -3.0, "poles": -2.5, "rod": -1.7, "rods": -1.8, "stick": -1.0, "sticks": -1.0,
    "pin": -1.0, "pins": -1.3, "peg": -1.5, "shaft": -0.7, "stem": -1.0, "stems": -1.6,
    "pipe": -0.6, "pipes": -0.6, "wire": -0.55, "strap": -1.4, "pot": -1.3, "pots": -1.8,
    "pad": -0.9, "pads": -1.5, "shelf": -0.9, "pier": -1.0, "chair": -0.5, "chairs": -1.1,
    "hole": -0.5, "holes": -0.5, "spring": -0.5, "springs": -0.5, "rack": -0.9,
    "string": -0.3, "strings": -0.6, "bars": -0.7, "bar": -0.2, "handle": -0.25,
    "handles": -0.45, "fork": -0.65,
}
ENDS_CONTEXT = {"opposite", "one", "each", "other", "upper", "lower", "leading", "opposed",
                "inlet", "outlet", "tight"}
CODE_FACTOR = 0.25


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = _word(raw)
    prev_raw = prefix.token_strings[-2] if len(prefix) > 1 else ""
    prev = _word(prev_raw)
    if raw.strip() == "··":
        return carry, 0.97
    if raw.strip() == "String":
        return carry, 0.0
    in_prose = prev_raw.strip().isalpha() or prev in ("a", "the")
    if word in ("end", "ends"):
        if prev in ENDS_CONTEXT:
            return carry, -4.5
        if word == "ends":
            return carry, -1.1 if in_prose else 0.0
        return carry, (-0.6 if in_prose else 0.0)
    if word == "bed":
        return carry, -1.7
    if word in OBJECT:
        return carry, OBJECT[word] * (1.0 if in_prose else CODE_FACTOR)
    return carry, 0.0

programs.sol:
"""A local lexical-grammar approximation, not a complete account of the component.

Degree and reference words respond strongly to determiners and possessives:
compare 'the most', 'the very', 'this particular', and 'any given'.
Smaller rules cover coordination, infinitives, friendship/family words,
and a few conventional expressions. Other contexts receive zero.

Only the current token and two preceding nonblank tokens are retained.
ASCII word fragments are suppressed; history resets at document boundaries.
The fitted constants approximate activation sizes, not probabilities.
"""
from functools import lru_cache
import wordnet

READS = ()
POSSESSIVES = {'my', 'your', 'his', 'her', 'its', 'our', 'their', "'s", '’s'}
DEMONSTRATIVES = {'this', 'that', 'these', 'those'}
COPULAS = {'am', 'is', 'are', 'was', 'were', 'be', 'been', 'being', "'s", '’s'}
PERSONAL_PRONOUNS = {'you', 'he', 'she', 'we', 'they', 'me', 'him', 'her', 'us', 'them'}


@lru_cache(maxsize=4096)
def verb_forms(word):
    return set(wordnet.base_forms(word)) | {word}


def response(word, previous, before):
    possessive = previous in POSSESSIVES
    pointing = previous in DEMONSTRATIVES
    definite = previous == 'the'
    if word == 'most':
        if possessive:
            return 2.026
        if definite or before == 'the':
            return 1.408
        if previous in COPULAS:
            return 0.9
        if previous == 'and':
            return 0.788
        return 0.112
    if word == 'very':
        if pointing or (possessive and previous not in {"'s", '’s'}):
            return 4.4
        if definite:
            return 2.729
        if previous == 'you':
            return 2.65
        if previous in {'it', 'them', 'him', 'her'}:
            return 1.0
        if previous in {'and', 'some', 'all', "'s", '’s', 'very'}:
            return 1.112
        return 0.4
    if word == 'particular':
        if pointing:
            return 3.65
        if possessive or previous == 'any':
            return 2.8
        if definite:
            return 1.7
        return 0.491 if previous in {'a', 'an', 'no'} else 0.078
    if word == 'specific':
        if possessive:
            return 3.5
        if definite:
            return 2.212
        if pointing or previous in {'any', 'one'}:
            return 1.5
        return 0.211 if previous in {'a', 'an', 'no'} else 0.078
    if word == 'given':
        if previous == 'any':
            return 3.5
        if definite:
            return -0.469
        return 0.739 if previous in {'a', 'an'} else 0.055
    if word == 'same':
        return 3.2 if pointing or previous == 'very' else 0.36
    if word == 'respective':
        if possessive or previous == 'each':
            return 3.0
        return 1.5 if definite else 0.65
    if word == 'own':
        if previous in {'its', 'their'}:
            return 0.593
        return 0.917 if possessive or previous == 'very' else 0.175
    if word == 'latter':
        return 2.4 if pointing else 0.194
    if word == 'more':
        if definite or previous in {'a', 'an'}:
            return 0.977
        if previous in COPULAS or previous in {'much', 'even'}:
            return 0.717
        if previous in {'no', 'any', 'one', 'two', 'few', 'have', 'has', 'need'}:
            return 0.086
        return 0.441
    if word == 'less':
        return 0.205
    if word == 'too':
        return 0.414
    if word == 'so':
        if previous in {'just', 'you'}:
            return 1.4
        if previous in COPULAS:
            return 0.557
        return 0.259 if previous and previous[-1].isalpha() else -0.013
    # A small multilingual vocabulary of degree and sameness words.
    if word in {'más', 'daha', 'более', '더', 'ganz'}:
        return 1.138
    if word in {'più', '更', '更加', '最', '很'}:
        return 0.659
    if word in {'plus', 'mais'}:
        return 0.696 if previous and previous[-1].isalpha() else 0.059
    if word in {'mesmo', 'même', 'mismo', 'misma'}:
        return 0.786
    if word in {'自身', '自己', '自己的'}:
        return 0.2
    # Emphatic quantification and coordination.
    if word in {'a', 'an'} and previous in {'such', 'quite'}:
        return 0.895
    if word == 'the' and previous in {'and', 'or'}:
        return 0.306
    if word == 'and':
        if previous == 'each':
            return 2.5
        if previous == 'any':
            return 1.0 if before == 'if' else 2.2
        if previous == 'you':
            return 1.3
        if previous in PERSONAL_PRONOUNS or possessive:
            return 0.602
    if word == 'or' and (possessive or previous in PERSONAL_PRONOUNS or
                         previous in {'whether', 'may'}):
        return 1.236
    if word == 'every' and previous == 'and' and before == 'each':
        return 3.8
    if word in {'single', 'individual'} and previous in {'each', 'every'}:
        return 1.7
    if word in {'all', 'any'} and previous in {'and', 'or'}:
        return 0.439
    if word == 'various':
        return 1.157 if definite else -0.024
    # Infinitive constructions: continuation/choice versus obligation/instruction.
    if word == 'to':
        forms = verb_forms(previous)
        if 'continue' in forms:
            return 1.311
        if 'choose' in forms:
            return 1.444
        if forms & {'decide', 'seek', 'refuse', 'appear'}:
            return 0.6
        if 'forget' in forms:
            return -1.4
        if previous == 'supposed':
            return -0.923
        if previous in {'how', 'expected', 'required'}:
            return -0.534
        if previous == 'had':
            return -0.802
        if previous in {'have', 'has'} or previous in COPULAS:
            return -0.316
    if word == 'how':
        forms = verb_forms(previous)
        if forms & {'show', 'demonstrate', 'explain'}:
            return -0.709
        if previous == 'you':
            return -0.8
    if word in {"'s", '’s'} and previous == 'let':
        return -0.433
    if word == 'of' and previous in {'kind', 'kinds', 'type', 'types', 'sort', 'sorts'}:
        return 0.524
    if word.removesuffix('s') == 'friend':
        return -1.807 if possessive else -0.536
    if word == 'family' and possessive:
        return -0.713
    # Lexicalized intensification, recurrence, and a devotional title.
    if word == 'well' and previous == 'may':
        return 2.0
    if word == 'now' and previous == 'every':
        return 0.7
    if word == 'and' and previous == 'now' and before == 'every':
        return 0.7
    if word == 'then' and previous == 'and' and before == 'now':
        return 0.3
    if word == 'lady' and previous == 'our':
        return 1.45
    if word in {'country', 'nation', 'court', 'office'}:
        if previous == 'this':
            return 1.8
        if previous == 'our':
            return 1.3
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous = before = ''
    else:
        _, previous, before = carry
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    # Do not mistake an English word-ending (e.g. '-less') for a new word.
    continuation = (prefix.position > 0 and
                    prefix.document_ids[-2] == document and
                    word.isascii() and word.isalpha() and
                    raw[:1].isalpha() and
                    prefix.token_strings[-2][-1:].isalpha())
    value = 0.0 if continuation else response(word, previous, before)
    # Capitalized English labels such as 'Cost Plus' are not French degree words.
    if word == 'plus' and raw.strip() != 'plus':
        value = 0.0
    if word:
        return (document, word, previous), value
    return (document, previous, before), value

programs.haiku:
"""Draft 6: words that grade or single out a noun phrase (boosted right after a determiner),
plus two small constructions: infinitive 'to' and 'of' after kind-nouns."""
READS = ()

# activation when the word is not right after a determiner
PLAIN = {" most": 0.3, " more": 0.5, " very": 0.5, " too": 0.4, " less": 0.3, " plus": 0.6,
         " so": 0.1, " own": 0.8, " same": 0.5, " latter": 1.5, " respective": 0.5,
         " particular": 0.3, " specific": 0.3, " various": 0.0,
         "更": 0.8, "最": 0.8, " más": 1.1, " mais": 0.9, " mesmo": 1.3, " самые": 2.5, " более": 1.0, " daha": 1.0}
# extra value when the word directly follows a determiner
BOOST = {" most": 1.2, " very": 2.7, " particular": 3.0, " specific": 1.6, " respective": 2.0,
         " various": 1.3, " too": 0.5, " more": 0.4}
DETERMINERS = {" the", " The", " this", " that", " their", " his", " her", " its", " our", " your", " my",
               " those", " these"}
# 'to' after verbs of continuing or choosing ('continue to', 'chose to') fires; after 'how', 'supposed', 'forget' it doesn't
TO_UP = {" continue", " continued", " continues", " decides", " decided", " chose", " choose", " seek", " refused"}
TO_DOWN = {" how", " forget", " supposed", " had", " have", " is", " was", " has", " required", " needs"}
KIND_NOUNS = {" type", " types", " kind", " kinds", " sort", " form", " manner", " combination"}

def step(carry, prefix, upstream):
    t = prefix.position
    w = prefix.token_strings[t]
    if t == 0:
        return None, 0.0
    prev = prefix.token_strings[t - 1]
    if w == " to":
        return None, 0.9 if prev in TO_UP else (-0.5 if prev in TO_DOWN else 0.0)
    if w == " of":
        return None, 0.5 if prev in KIND_NOUNS else 0.0
    value = PLAIN.get(w, 0.0)
    if prev in DETERMINERS:
        value += BOOST.get(w, 0.0)
    return None, value

programs.sol:
"""A local detector for software-maintenance scaffolding.

Predict negative spikes on unified-diff headers, path roots, and familiar
file/change-report phrases. Abbreviated-month and line-number blanks are a
secondary response. A few test-output delimiters have positive responses.
These rules capture recognizable strong responses, not all the component's
weaker lexical effects. Only the last 240 characters of each document are kept.
"""
import calendar
import re

READS = ()
MONTHS = frozenset(calendar.month_abbr[1:])
EDITING = re.compile(
    r'\b(?:files?|tests?|git|code|PR|patch|fix|implement\w*|'
    r'renam\w*|updat\w*|summary|review)\b', re.I
)


def diff_marker(s, text, previous):
    """Recognize the fixed words and source/destination prefixes of a patch."""
    if s == 'diff' and (not text or text.endswith('\n')):
        return -1.40
    if s == ' --' and text.endswith('diff'):
        return -0.97
    if s == 'git' and text.endswith('diff --'):
        return -3.52
    if s == ' a' and text.endswith('diff --git'):
        return -5.51
    if s == ' b' and re.search(r'diff --git a/[^\n]*$', text):
        return -2.46
    if s == 'index' and text.endswith('\n'):
        return -3.06
    if s == ' ' and re.search(r'(?:^|\n)index$', text):
        return -2.47
    if s == ' a' and re.search(r'(?:^|\n)---$', text):
        return -5.81
    if s == ' b' and re.search(r'(?:^|\n)\+\+\+$', text):
        return -3.73
    if s == '+++' and text.endswith('\n'):
        return -2.70
    if s == '@@' and text.endswith('\n'):
        return -0.94
    if s == ' -' and previous == '@@':
        return -2.78
    if s == ' diff' and text.endswith(' git'):
        return -2.56
    if s == 'stat' and text.endswith('git diff --'):
        return -3.28
    return None


def activation(s, text, previous):
    patch = diff_marker(s, text, previous)
    if patch is not None:
        return patch

    # Absolute paths, including two tokenizations of the workspace root.
    if s == '/workspace':
        return -1.86
    if s == 'workspace' and text.endswith('/'):
        return -1.41
    if s in ('opt', 'usr', 'tmp', 'root') and text.endswith('/'):
        return -0.93
    if s == '/local' and previous == 'usr':
        return -0.96
    if s == ' "/' and previous == ' File':
        return -1.28
    if s == ' /':
        return -0.81 if previous in (':', ' file') else -0.19
    if s in ('.git', '.github'):
        return -0.94
    if s == '/' and previous in ('.git', '.github', 'git'):
        return -0.60

    # Whitespace starting a numeric date or line-number field.
    if s == ' ':
        month = previous.strip()
        if month in MONTHS and (month != 'May' or re.search(r'\d+ May$', text)):
            return -0.93
        if re.search(r'Created by [^\n]* on$', text):
            return -1.44
        if previous.strip().lower() == 'line':
            return -0.79 if text.endswith('(line') else -0.69
    if s == 'ed' and previous == ' Comment':
        return 0.94

    # Software-change reports and editor boilerplate.
    if s == ' changes':
        if text.endswith('summary of the'):
            return -4.47
        if text.endswith('Review the'):
            return -3.94
        if EDITING.search(text):
            return -1.58
        if previous == ' the':
            return -1.18
        if previous == ' your':
            return -2.80
        if previous in (' all', ' necessary', ' minimal', ' breaking'):
            return -0.89
        return -0.18
    if s == ' file':
        if previous.strip().lower() in ('changed', 'modified', 'renamed', 'deleted'):
            return -3.01
        if text.endswith('Edit the'):
            return -2.11
        if previous == 'The':
            return -1.23
        return -0.61 if previous in (' the', ' same') else -0.48
    if s == ' files':
        return -0.72
    if s == ' change' and EDITING.search(text):
        return -0.45
    if s == ' Files' and EDITING.search(text):
        return -1.64
    if s == ' changed' and previous.strip().lower() in ('file', 'files'):
        return -4.63
    if s == 'Review':
        return -0.47
    if s in (' repository', ' repo', ' directories'):
        return -0.63

    # Version-control terminology and familiar maintenance filenames.
    if s in (' request', ' Request') and previous.strip().lower() == 'pull':
        return -4.47
    if s == ' pull' and previous.strip() == 'Merge':
        return -3.98
    if s == 'its' and text.endswith('comm'):
        return -3.65
    if s == '-off' and text.endswith('Signed'):
        return -5.20
    if s == 'LOG' and text.endswith('CHANGE'):
        return -2.25
    if s in ('Changes', ' Changes') or (s == 'ANGES' and text.endswith('CH')):
        return -1.91
    if s == 'file' and text.endswith('Make'):
        return -1.16
    if s == 'issue' and previous == '<':
        return -1.59
    if s in (' Git', 'git'):
        return -0.71

    # Test/build output and filename delimiters.
    if s in (' SUCCESS', ' FAILED') and previous == 'BUILD':
        return -3.01
    if s in (' Coverage', ' coverage') and (
        re.search(r'={3,}$', text) or previous in ('Diff', ' tests')
    ):
        return -2.73
    if s == ' (' and previous in ('.ts', '.js', '.tsx'):
        return -1.98
    if s == ':' and previous == '.go':
        return 0.93
    if s == '::' and previous == '.py':
        return 0.50
    if s == ' PASS' and text.endswith('---'):
        return 0.82
    if s == '.jar':
        return 0.97
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, previous = '', ''
    else:
        _, text, previous = carry
    token = prefix.token_strings[-1]
    value = activation(token, text, previous)
    return (doc, (text + token)[-240:], token), value

programs.haiku:
"""layers.1.mlp.down_proj:3130: a negative detector for git, diff and file-path vocabulary.

What it does: this component is quiet on most text. It goes negative on the
vocabulary of version control and file changes, and much more strongly inside
coding-agent transcripts and git diffs. The cues, strongest first:
  - the "a/" and "b/" of a git diff header ("diff --git a/x b/x", "--- a/x", "+++ b/x"),
    where it responds most strongly;
  - the " -" of a hunk header ("@@ -12,3 +12,4 @@");
  - "Review the changes" and "Edit the file", phrases that agent tools print;
  - "pull request" (GitHub merge text);
  - the word "workspace" (as in "/workspace/repo"), which always fires;
  - git words ("git", ".git", "diff", "index", "repository"), stronger in agent text;
  - file and change words ("changes", "file", "files", "Modified", "Review"),
    stronger in agent text;
  - the space inside a forum date after a month name ("Joined: Tue Nov 05").
A run of middle-dot fill characters "··" is strongly positive.

It reads the current token, the previous token and a rolling 40-character text
tail, so it is causal. Its carried state resets at each document boundary.
"""

READS = ()

WORKSPACE = {"workspace", "/workspace"}
GIT = {"git", ".git", "diff", "index", "+++", "@@", "commit", "HEAD", "repository", "repo"}
FILE_WORDS = {"changes", "Changes", "file", "files", "File", "Files", "Modified", "edited", "Added", "Review"}
MONTHS = {"Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"}
DIFF_HEADER_PREV = {"git", "---", "+++"}
AGENT_MARKS = ("<tool_", "OBSERVATION", "<|im_start|>", "diff --git")
FILL = {"··"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = tok.strip()
    toks = prefix.token_strings
    prev = toks[-2].strip() if len(toks) > 1 else ""
    prev2 = "".join(toks[-3:-1]) if len(toks) > 2 else ""

    # Carried state: has an agent or diff marker appeared in this document so far.
    new_doc = len(prefix.document_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]
    seen_agent, tail = carry if (carry is not None and not new_doc) else (False, "")
    tail = (tail + tok)[-40:]
    seen_agent = seen_agent or any(m in tail for m in AGENT_MARKS)

    if tok in {" a", " b"} and prev in DIFF_HEADER_PREV:
        v = -5.5 if tok == " a" else -3.5
    elif tok == " -" and prev == "@@":
        v = -2.8
    elif word == "request" and prev in {"pull", "Pull"}:
        v = -4.0
    elif word == "changes" and prev2.endswith("Review the"):
        v = -3.9
    elif word == "file" and prev2.endswith("Edit the"):
        v = -2.1
    elif word in WORKSPACE:
        v = -1.6
    elif word in GIT:
        v = -1.25 if seen_agent else -0.45
    elif word in FILE_WORDS:
        v = -0.9 if seen_agent else -0.4
    elif tok == " " and prev in MONTHS:
        v = -0.8
    elif tok in FILL:
        v = 1.4
    else:
        v = 0.0
    return (seen_agent, tail), v

programs.sol:
"""A rough numerical-continuation detector, especially for elapsed years.

Estimate a trailing quantity from digits, English number words or Han numerals.
Use its log magnitude, written zeros and separators to score selected endings.
Long year spans and ancient dates are generally positive; money, area and
quantity-following prepositions generally negative. These are approximations,
not a full account of the component. Unrecognized endings receive zero.
'Ago' and 'since' also use nearby year words and perfect-tense/time cues.
Repeated middle dots have a separate negative decorative-punctuation rule.
Only the last 100 decoded characters are carried; documents reset this state.
"""
import re
import math
import unicodedata
import inflect

READS = ()
_engine = inflect.engine()
NUMBER_WORDS = {_engine.number_to_words(i): i for i in range(1, 100)}
NUMBER_WORDS.update({_engine.ordinal(k): v for k, v in list(NUMBER_WORDS.items())})
SCALES = {'hundred': 100, 'thousand': 1000, 'million': 10**6,
          'billion': 10**9, 'trillion': 10**12,
          'миллионов': 10**6, 'миллиона': 10**6,
          'millionen': 10**6, 'millones': 10**6,
          '万': 10000, '萬': 10000, '亿': 10**8, '億': 10**8}

YEAR_WORDS = {'year', 'years', 'лет', 'года', 'год', 'г', 'гг',
              'jahre', 'jahren', 'año', 'años', 'ans', 'jaar', 'anni'}
NUMERAL = re.compile(r'([0-9](?:[0-9,.]*[0-9])?)[+]*(?:st|nd|rd|th)?$')
WORD = re.compile(r'([^\W\d_]+)[- ]*$')


def quantity(text):
    """A trailing Arabic, spelled-out, or Han number, with optional scale."""
    text = text.rstrip(' \t\n-+')
    text = re.sub(r'\bof$', '', text).rstrip()
    scale = 1
    m = WORD.search(text.lower())
    if m and m[1].rstrip('s') in SCALES:
        scale = SCALES[m[1].rstrip('s')]
        text = text[:m.start()].rstrip(' -')
    vague = WORD.search(text.lower())
    if vague and vague[1] in {'many', 'several', 'few', 'couple'}:
        count = 10 if vague[1] in {'many', 'several'} else 3
        return count * scale, 0, 0, scale > 1
    m = NUMERAL.search(text)
    if m:
        digits = re.sub(r'[^0-9]', '', m[1])
        try:
            value = float(m[1].replace(',', ''))
        except ValueError:
            value = 0
        return value * scale, len(digits), digits.count('0'), scale > 1
    compound = re.search(r'([a-z]+-[a-z]+)$', text.lower())
    m = compound if compound and compound[1] in NUMBER_WORDS else WORD.search(text.lower())
    if m and m[1] in NUMBER_WORDS:
        n = NUMBER_WORDS[m[1]]
        return n * scale, len(str(n)), str(n).count('0'), scale > 1
    if scale > 1:
        return scale, 0, 0, True
    if text and unicodedata.numeric(text[-1], None) is not None:
        chars = []
        for ch in reversed(text):
            if unicodedata.numeric(ch, None) is None:
                break
            chars.append(ch)
        nums = [unicodedata.numeric(c) for c in chars]
        value = max(nums)
        if value >= 10:
            value *= max(1, sum(n for n in nums if n < 10))
        return value, len(chars), sum(n == 0 for n in nums), False
    return None


def predict(before, token):
    before = unicodedata.normalize('NFKC', before)
    word = token.strip().lower()
    qtext = before
    previous_year = False
    unit_scale = 1
    group = None
    if word in {'years', '-year', '-years'}:
        group = 'years'
    elif word == 'year':
        group = 'year'
    elif (word in YEAR_WORDS - {'year', 'years'}
          and (token.startswith(' ') or not word.isascii())):
        group = 'foreign_year'
    elif re.fullmatch(r'(?:多|周)?年(?:的|间|初)?|년|岁|歲', word):
        group = 'han_year'
    elif word in {'anniversary', 'anniversaries'}:
        group = 'years'
    elif (word in {'ago', 'since', '-old'}
          or word in {'前', '来', '來'} and before.endswith('年')):
        group = (word if word in {'ago', 'since'} else
                 'old' if word == '-old' else 'ago')
        m = re.search(
            r'(?:\b|-)(years?|decades?|centur(?:y|ies)|millenni(?:um|a))[ -]*$',
            before.lower())
        if before.endswith('年'):
            previous_year = True
            qtext = before[:-1]
        if m:
            previous_year = group == 'since' or m[1] != 'year'
            qtext = before[:m.start()]
            if m[1].startswith('decad'):
                unit_scale = 10
            elif m[1].startswith(('centur', 'millenn')):
                unit_scale = 100 if m[1].startswith('centur') else 1000
    elif token.strip() in {'BC', 'BCE', 'AD', 'CE'}:
        group = 'era_bc' if word.startswith('b') else 'era_ad'
    elif word in {'.c', 'c', '.e'} and re.search(r'\b[BbAa](?:\.| )*$', before):
        group = 'era_bc' if re.search(r'\b[Bb](?:\.| )*$', before) else 'era_ad'
        qtext = re.sub(r'\b[BbAa](?:\.| )*$', '', before)
    elif word in {'in', 'of', 'on', 'at', 'by', 'for', 'to', 'from', 'after'}:
        group = word if word in {'in', 'of'} else 'preposition'
        qtext = re.sub(r'\b(?:dollars?|euros?|pounds?)$', '', before.lower()).rstrip()
    elif word in {'号', '號'}:
        group = 'address_number'
    elif word in {'square', '-square', '平方米', '平方'}:
        group = 'area'
    elif word in {'分', '份', 'part', 'parts'}:
        group = 'part'
    elif word in {'people', 'persons', 'person', '人', '户', '戶', '辆', '輛',
                  '个', '個', '项', '項', '多项', '多項', 'page', 'pages', '-page',
                  'seat', '-seat', 'tonnes', '吨', '噸'}:
        group = 'count_unit'
    elif word in {'円', '块', '塊', '欧', '歐', '人民币'}:
        group = 'money'
    elif (word.rstrip('s') in SCALES
          or re.fullmatch(r'[万萬亿億]+(?:元|美元|人|户|戶)', word)):
        group = 'scale'
    elif word == 'px':
        group = 'pixels'
    elif word == '.m' and before.endswith((' a', ' p')):
        group = 'morning' if before.endswith(' a') else 'afternoon'
        qtext = before[:-2].rstrip()
    if group is None:
        return 0.0
    if group.startswith('era_'):
        qtext = re.sub(r'\bcentur(?:y|ies)[ -]*$', ' hundred', qtext)
        qtext = re.sub(r'\bmillenni(?:um|a)[ -]*$', ' thousand', qtext)
    q = quantity(qtext)
    if q is not None and q[0] == 0 and group in {'years', 'han_year', 'ago', 'old'}:
        q = (10 ** q[1], q[1], q[2], q[3])
    if unit_scale > 1:
        count = q[0] if q else 1
        value = count * unit_scale
        digits = str(int(value))
        q = (value, len(digits), digits.count('0'), False)
    if q is None:
        n = d = zeros = scale = 0
        present = 0
    else:
        value, d, zeros, scale = q
        n = min(6, math.log10(max(1, value)))
        present = 1
    perfect = group == 'since' and bool(re.search(
        r"\b(?:been|has|have|had|haven.t)\b", before.lower()))
    time_hint = group == 'since' and bool(re.search(
        r'\b(?:ever|time|while)$', before.lower()))
    separator = present and bool(re.search(r'\d,\d{3}(?:[\d,.]*)$', qtext))
    currency = (group in {'in', 'of', 'money'} and present
                and any(c in before[-30:] for c in '$€£¥₹'))
    # n = log10(quantity), short = the part below 100.
    # Written zeros and commas distinguish round/large printed quantities.
    short = min(n, 2)
    digits = min(d, 4)
    zeros = min(zeros, 3)
    if group == 'years':
        return (-0.2 - 0.5 * present + 1.35 * n - 0.2 * short
                - 0.15 * digits + zeros + 1.4 * scale + 1.3 * separator)
    if group == 'year':
        return -0.1 + 0.3 * (n + short)
    if group == 'foreign_year':
        return (-0.05 + 0.7 * present + 1.1 * n - 0.8 * digits + 0.35 * zeros
                + 0.8 * scale)
    if group == 'han_year':
        return 1.25 * short - 0.75 * max(0, n - 2) - 0.25 * digits
    if group == 'era_bc':
        return (0.1 + 0.3 * present + 1.5 * n + short - 0.6 * digits + 1.3 * zeros
                + scale)
    if group == 'era_ad':
        return -0.1 + 0.5 * present - 0.1 * n + 0.3 * short + 0.15 * digits
    if group == 'since':
        return (0.05 + 1.4 * previous_year + 0.4 * perfect
                + 1.3 * perfect * previous_year + 1.3 * time_hint)
    if group == 'ago':
        return 0.05 - 0.6 * present + 0.35 * n + 0.85 * short + zeros + 0.6 * previous_year
    if group == 'old':
        return 4 * max(0, n - 2) + (0.5 * zeros if n > 2 else -0.1)
    if group in {'morning', 'afternoon'}:
        return (1.6 if group == 'morning' else 0.5) * present
    if group == 'in':
        return (-0.4 * n + 0.2 * short + 0.1 * digits - scale - 0.3 * separator
                - 0.85 * currency)
    if group == 'of':
        return (0.05 * digits - 0.25 * zeros + 0.1 * scale - 0.9 * separator
                - 0.55 * currency)
    if group == 'preposition':
        return -0.25 * scale - 0.2 * separator
    if group == 'money':
        return -0.8 * present - 0.6 * n + 0.5 * digits - 0.1 * zeros - 1.3 * scale
    if group == 'area':
        return 0.1 + 0.3 * present - 0.2 * digits - 0.35 * zeros - 0.5 * separator
    if group == 'part':
        return -0.5 * n + 0.35 * short + 0.1 * digits
    if group == 'count_unit':
        return 0.3 * n - 0.2 * short - 0.1 * digits + 0.15 * zeros + 0.25 * scale
    if group == 'scale':
        return -0.15 * present + 0.4 * n - 0.15 * short + 0.4 * zeros
    if group == 'address_number':
        return 0.15 - 0.15 * n - 0.2 * zeros
    if group == 'pixels':
        return -0.3 - 0.5 * present - 0.2 * n + 0.8 * short + 0.4 * digits + 0.2 * zeros
    return 0.0

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(before, token)
    if len(token) > 1 and token.strip('·') == '':
        value = -1.04 * len(token)
    return (doc, (before + token)[-100:]), float(max(-12, min(12, value)))

programs.haiku:
"""Quantity words in text: the component rises on the word that names a span of years or a
large count right after a number ('20 years', '1973年', '500 billion', '3 BC', 'ago', 'since')
and falls on the word after a money amount ('$35,000 in', '2.8万円', dot leaders).

Positive: year-span words after a number, scaled by the number's size (bigger number, bigger
value); 年 after a four-digit year; BC/AD after a large number; 'ago'/'since' after a year span;
billion/million/萬 after a number.
Negative: in/of/on/at right after a money amount or a scale word (million, billion, 万),
円 after 万, and a run of middle dots (table leaders), a strong fixed value.
"""

READS = ()

YEAR_WORDS = {"years", "year", "-year", "周年", "Jahren", "Jahre", "Jahr", "лет", "год", "năm", "anos"}
NUMBER_WORDS = {"hundred": 100, "hundreds": 100, "thousand": 1000, "thousands": 1000,
                "twenty": 20, "thirty": 30, "forty": 40, "fifty": 50, "sixty": 60,
                "seventy": 70, "eighty": 80, "ninety": 90}
PREPS = {"in", "of", "on", "at"}
MONEY = {"$", "£", "€", "¥"}
SCALE = {"million", "billion", "万", "萬", "億"}


def number_before(strings, end):
    """The number written just before token `end` (digits, commas, dots), and the index before it."""
    digits, i = "", end - 1
    while i >= 0 and (strings[i].strip().isdigit() or strings[i].strip() in {",", "."}):
        digits = strings[i].strip() + digits
        i -= 1
    if digits:
        try:
            return float(digits.replace(",", "")), i
        except ValueError:
            pass
    if end >= 1 and strings[end - 1].strip() in NUMBER_WORDS:
        return float(NUMBER_WORDS[strings[end - 1].strip()]), end - 2
    return None, i


def year_value(n):
    """How strongly a year-span word fires after the number n."""
    if n < 10:
        return 0.0
    if n < 20:
        return 0.2
    if n < 40:
        return 1.3
    if n < 100:
        return 1.9
    return 2.5


def step(carry, prefix, upstream):
    s = prefix.token_strings
    if len(s) < 2:
        return None, 0.0
    cur = s[-1].strip()
    prev = s[-2].strip()
    if cur and set(cur) == {"·"} and len(cur) >= 2:
        return None, -2.0
    if cur == "円" and prev in {"万", "萬"}:
        return None, -4.0
    if cur in {"ago", "since"} and prev in YEAR_WORDS:
        return None, 1.5
    n, i = number_before(s, len(s) - 1)
    if n is None:
        return None, 0.0
    if cur in YEAR_WORDS:
        return None, year_value(n)
    if cur == "年":
        return None, 0.6 if n >= 1000 else year_value(n)
    if cur in {"BC", "AD", "CE"}:
        return None, 3.0 if n >= 100 else 0.0
    if cur in {"billion", "million"}:
        return None, 1.5 if n >= 40 else 0.3
    if cur in {"万", "萬"}:
        return None, 1.0
    if cur in PREPS and (prev in SCALE or any(t.strip() in MONEY for t in s[max(0, i - 1):i + 1])):
        return None, -2.5
    return None, 0.0

programs.sol:
"""A spelling-based detector for short -y and -ie word endings.

Track the unfinished ASCII word (at most 50 letters). Predict mainly
negative activity when a small token completes an ending, especially after
an English-looking base or doubled letter. Word frequency and vowel-group
counts separate these from common words, longer formations, and isolated
letters. A few
rules also cover complete short words. This is not a pronunciation model.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=20000)
def frequency(word):
    # Logarithmic English frequency: higher means more common.
    return zipf_frequency(word, 'en') if word else 0.0


def predict(word, token, previous, continued):
    lower = word.lower()
    match = re.search(r'(y|ie|ies|ied|ier)$', lower)
    if not match or len(word) <= len(match.group()):
        return -0.002
    ending = match.group()
    stem = lower[:-len(ending)]
    doubled = len(stem) > 1 and stem[-1] == stem[-2]
    base = stem[:-1] if doubled else stem
    commonness = frequency(lower)
    base_advantage = max(frequency(stem), frequency(base)) - commonness
    vowel_groups = len(re.findall('[aeiouy]+', lower))
    token_length = len(token.strip())

    # The ending is emitted by itself.
    if continued and len(token) <= len(ending):
        if vowel_groups <= 1:
            return 0.74
        if vowel_groups >= 3:
            return -0.49
        if commonness < 1.8:
            return -1.13
        if base_advantage > 1.0:
            return -4.08
        if token_length >= 3:
            return -0.71
        if commonness >= 3.6:
            return -1.08
        return -3.10

    # A larger piece completes a familiar-looking prefix.
    if continued and frequency(previous.lower()) >= 1.8:
        if vowel_groups != 2:
            if vowel_groups == 1:
                return 0.22
            return 0.0
        if doubled:
            if token_length >= 4:
                return -1.27
            if base_advantage <= 1.8:
                return -4.97
            return -2.86
        if stem.endswith('k'):
            return -2.43
        if lower.endswith('dy'):
            return -1.95
        return -0.48

    # Other short words.
    if vowel_groups == 2 and len(word) <= 7 and 1.8 <= commonness < 4.7:
        if doubled and not stem.endswith('r'):
            if word[0].isupper():
                return -1.42
            return -0.68
        if stem.endswith('k'):
            return -0.72
        if ending == 'ie':
            return -0.60
        if base_advantage > 0.5:
            return -0.41
    return -0.03


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    token = prefix.token_strings[-1]
    match = re.search(r'[A-Za-z]+$', token)
    tail = match.group() if match else ''
    continued = bool(tail and len(tail) == len(token) and previous)
    word = (previous + tail if continued else tail)[-50:]
    return (document, word), predict(word, token, previous, continued)

"""A surface-spelling approximation to a west/web lexical feature.

Short West/Western and web stems get the largest values; longer web words,
wed/wet, and a few non-English spellings get smaller or separate values.
Up to two preceding tokens handle split spellings: W + es is strongly
positive, while W followed by o/u is negative. Most other positions return
zero. There is also a small response to repeated middle dots. State resets
for each document.
"""
READS = ()


def lexical_value(token):
    word = token.lstrip(' \t\n./_-').lower()
    capital = token.lstrip(' \t\n./_-')[:1].isupper()
    if token.lower() == '-west' and not capital:
        return 2.3
    if word == 'western':
        return 4.6
    if word == 'west':
        return 5.1 if capital else 3.8
    if word in (
        'northwest', 'southwest', 'midwest',
        'northwestern', 'southwestern',
    ):
        return 2.8 if capital else 1.7
    if word in ('wes', 'wesley', 'wessex'):
        return 2.7
    if word.startswith('web'):
        if word.startswith('website'):
            return 0.75
        if word.startswith('webpage'):
            return 1.5
        if word.startswith('webhook'):
            return 0.55
        if word.startswith('webb'):
            return 0.3
        if word not in ('web', 'webs', 'weber', 'webster'):
            return 0.0
        if token.startswith('.'):
            return 6.1
        if not token[:1].isspace():
            return 3.5
        return 2.5
    if word == 'wed':
        return 1.7 if capital else 3.2
    if word == 'wet':
        return 1.0
    if word.startswith('weg'):
        return 0.9
    if word.startswith(('week', 'weak', 'weather', 'wednes')):
        return 0.2
    if token == '西':
        return 2.3
    if token in ('西部', '西方', '西北', '西南'):
        return 2.0
    if token and set(token) == {'·'} and len(token) > 1:
        return 0.65
    return 0.0


def predict(token, previous, earlier=''):
    value = lexical_value(token)
    before = previous.strip().lower()
    after = token.lower()
    # Romance-language spellings of the west direction.
    if before in ('o', 'noro', 'suro', 'oro') and after == 'este':
        return 10.0 if before == 'o' else 7.5
    if before == 'ou' and after == 'est':
        return 8.0
    if before.endswith('west') and after == 'ern':
        return 6.0
    if before.endswith('west') and after == 'en':
        return 2.0
    # Split transliterations of web/we.
    if before in ('в', 'ві') and after.startswith('еб'):
        return 7.3
    if previous == 'เว' and token == '็บ':
        return 5.1
    if previous == 'ウ' and token == 'エ':
        return 5.5
    if token == 'ウェ':
        return 0.7
    isolated_w = before.strip('._/-') == 'w'
    if isolated_w and token == '3':  # W3, as in World Wide Web names
        return 3.4
    if (earlier + previous).lower().endswith('wes') and after == 'ley':
        return 3.1
    if token[:1].isalpha() and before.endswith('w'):
        if after in ('es', 'est', 'ester', 'eb'):
            return 6.7 if isolated_w else 3.5
        if after in ('ed', 'eds', 'eg', 'ego', 'ey'):
            return 3.0 if isolated_w else 1.5
        if after.startswith('e'):
            if isolated_w:
                return 1.2 if len(after) <= 3 else 0.4
            return 0.4 if len(after) <= 3 else 0.2
        if after.startswith('o'):
            return -1.1 if isolated_w else -0.4
        if after.startswith('u'):
            return -0.7 if isolated_w else 0.0
        return value
    if before == 'we' and token[:1].isalpha():
        if after.startswith(('b', 's')):
            return 3.0
        if after == 'ft':
            return 2.3
    return value


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous, earlier = ('', '')
    if carry is not None and carry[0] == doc:
        previous, earlier = carry[1:]
    return (doc, token, previous), predict(token, previous, earlier)

