"""Draft 5: whole-word values for WEST and WEB, ignoring leading punctuation."""
READS = ()

VALUE = {
    "west": 4.8, "western": 4.5, "westward": 4.0, "northwest": 3.0, "southwest": 1.5,
    "midwest": 2.0, "西": 2.3, "西部": 3.1, "oeste": 4.5, "ouest": 4.5,
    "web": 3.0, "webs": 2.5, "weber": 2.5, "webster": 2.5, "webpage": 1.5,
    "website": 0.8, "websites": 0.5, "веб": 3.0, "ウェブ": 3.0, "เว็บ": 3.0,
}

def step(carry, prefix, upstream):
    piece = prefix.token_strings[-1].strip().lower().lstrip("./-")
    return None, VALUE.get(piece, 0.0)

programs.sol:
"""Approximate a sparse, signed local-syntax feature.

It is positive on indented control flow, logging, and selected library calls;
it is negative on import constructions, TeX arguments, and copulas following
'This/These + noun phrase'. These are surface rules, not a general semantic
code classifier. The state is just a 160-character suffix and the last token,
reset at document boundaries. Unrecognized constructions stay near zero.
"""
import re
import sys

READS = ()
CONTROL = {'if', 'for', 'while', 'switch', 'foreach'}
ASSERTIONS = {'expect', 'assert', 'assertThat', 'assertEquals', 'assertEqual'}
LOGGING = {'log', 'info', 'debug', 'warn', 'warning', 'error', 'trace',
           'print', 'println', 'printf', 'Write', 'WriteLine', 'Printf',
           'Println', 'Log', 'LogError', 'LogWarning'}


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        before, previous = '', ''
    else:
        _, before, previous = carry
    value = response(token, before, previous)
    return (doc, (before + token)[-160:], token), value


def response(s, before, prev):
    word = s.strip()
    before = before.replace('\\n', '\n').replace('\\t', '\t')
    whitespace = prev.replace('\\n', '\n').replace('\\t', '\t').isspace()
    owner = re.search(r'([A-Za-z_]\w*)$', before)
    name = owner[1] if owner else prev.strip()

    # Import aliases, module introductions, and C header names.
    if word == 'as':
        m = re.search(r'\bimport\s+([\w.*]+)$', before)
        if m:
            return -9.96 if m[1] in {'numpy', 'pandas'} else -0.91
    if word == 'import':
        m = re.search(r'\bfrom\s+([\w.]+)\s*$', before)
        if m:
            module = m[1].split('.')[0]
            standard = module in sys.stdlib_module_names
            numeric = module in {'scipy', 'tqdm', 'PIL', 'pandas', 'numpy'}
            return -5.87 if standard or numeric else -1.06
        return -0.08
    if s == '.h' and '#include' in before[-90:]:
        return -4.63 if name in {'stdio', 'stdlib'} else -0.63
    if word == '#include':
        return -0.78
    importing = re.search(r'\b(?:import|using)\s+[\w.]+$', before)
    if importing and s in {'.stereotype', '.extern', '.annotation'}:
        return -5.75
    if word == 'collections' and before.endswith('std::'):
        return -7.47

    # Demonstrative descriptions: 'This number is', not 'is' in general.
    if word in {'is', 'was', 'are', 'were'}:
        m = re.search(r'\b(This|These|this|these)\s+([\w -]{1,60})$', before)
        if m and len(m[2].split()) <= 4 and not re.search(
                r'\b(is|was|were|are|can|has|have|will|would|should|it|they|not)\b',
                m[2]):
            if word == 'is':
                if m[1][0].islower():
                    return -0.12
                return -1.62 if len(m[2].split()) == 1 else -0.36
            return -0.50 if word == 'was' else -0.16

    # TeX argument boundaries, especially array-column and length settings.
    if s == '}{':
        if re.search(r'\\begin\{array$', before):
            return -9.82
        if re.search(r'\\setlength\{[^{}]*$', before):
            return -6.0
    if s in {'{', '['}:
        m = re.search(r'\\([A-Za-z]+)$', before)
        if m:
            if m[1] in {'hspace', 'vspace', 'color', 'setlength',
                        'includegraphics', 'usepackage'}:
                return -3.74
            if m[1] in {'mathbb', 'mathcal', 'mathbf', 'mathds',
                        'boxed', 'hat', 'vec'}:
                return -0.51
            return -0.12

    # Common runtime operations, distinguished from dotted import paths.
    if word.startswith('.') and word[1:].isidentifier():
        method = word[1:]
        if method in LOGGING:
            if name.lower() == 'console':
                return 1.92
            if name.lower() in {'logger', 'log', 'logging', 'trace', 'debug', 'out'}:
                return 1.25
            return 0.19
        if name == 'JSON':
            return 5.25 if method == 'parse' else 2.01
        if name in {'torch', 'tf', 'tensorflow'}:
            constructors = {'tensor', 'Variable', 'constant', 'arange', 'long'}
            return 3.62 if method in constructors else 0.15
        if name in {'np', 'numpy'}:
            if method in {'zeros', 'ones', 'empty', 'float', 'int', 'dtype'}:
                return -1.30
            if method in {'arange', 'mean', 'std', 'median', 'where'}:
                return 3.58
            return 1.40
        if name in {'pd', 'pandas'}:
            return 2.58
        if name == 'Math':
            return 2.09
        if name == 'Joi':
            return 2.62 if method == 'object' else 0.04
        if name == 'Object' and method in {'keys', 'values', 'entries', 'assign', 'create'}:
            return 4.16
        if method == 'Marshal':
            return 5.69
        if method in {'parseInt', 'parseFloat', 'valueOf', 'ToInt', 'Format', 'Sprintf'}:
            return 1.28
        if method in {'of', 'from'} and name[:1].isupper():
            return 1.34
        if importing:
            return -0.20
        if name in sys.stdlib_module_names:
            return 0.15
    if prev.strip() == '::':
        if word == 'move':
            return 6.62
        if word in {'new', 'construct'}:
            return 1.68
        if before.endswith('std::') and word.isidentifier():
            return 0.84
    if word == 'construct' and before.endswith('__'):
        return 3.39
    if word in {'_merge', '_encode', '_decode'} and name in {'array', 'json'}:
        return 5.36

    # Control-flow words are positive in C-like bodies, not ordinary prose.
    if word in CONTROL or word in ASSERTIONS:
        if whitespace:
            if word in ASSERTIONS:
                return 1.14 if word == 'expect' else 0.32
            if re.search(r'\b(def|elif|lambda|self|None|True|False)\b|:\s*\n', before):
                return 0.01
            if re.search(r'\b(let|mut|fn|func)\b|:=', before):
                return 0.39
            return 0.99 if ';' in before or '{' in before else 0.14
        if name in {'else', '{', '}', ';', ':'}:
            return 0.54
    if word == 'goto':
        return -1.09
    if word.startswith('@Slf'):
        return -4.37
    if word == '#[' or (word == 'derive' and before.endswith('#[')):
        return -0.81
    if word == '_modules' and before.endswith('node'):
        return 0.33

    # String specifications, annotations, and markup dimensions.
    if s.startswith('("') and name == 'scanf':
        return -3.62
    if s in {"('", '("', '(\\"'}:
        if name in {'DecimalFormat', 'axis'}:
            return -4.90
        if name in {'on', 'array', 'system', 'PathVariable', 'Repository', 'RequestParam'}:
            return -1.36
    if s.startswith('(String') and name == 'main':
        return -2.56
    if s in {'="', "='"}:
        if name in {'align', 'valign'}:
            return -2.05
        if name in {'width', 'height', 'cellpadding', 'cellspacing'}:
            return -0.70
    if len(s) > 1 and set(s) == {'·'}:
        return -0.43
    return -0.002
